with enrichment(grammar_id,formation_value,usage_value,nuance_value,examples_value) as (
  values
    ('b06e5382-f940-4a0f-bfaf-f5adca154665'::uuid,ARRAY['(i) {V/Adjective い} informal の']::text[],ARRAY['Use this construction to express A sentence-final particle used by a female or a child to indicate an explanation or emotive emphasis.. A sentence-final particle used by a female or a child to indicate an explanation or emotive emphasis.']::text[],ARRAY['【Related Expression: のだ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"A:どうして泣いているの？ B:お母さんがいないの。","japanese_furigana":"A:どうして泣いているの？ B:お母さんがいないの。","english":"A: How come you are crying? B: ''Cause mommy''s gone."},{"japanese":"あの人はとても優しいの。","japanese_furigana":"あの人はとても優しいの。","english":"He is so gentle, you know."}]'::jsonb),
    ('a3291689-be57-4f8c-9fc1-e0055762518a'::uuid,ARRAY['(i) Noun の Noun 田中さん の 家 Mr. Tanaka’s house']::text[],ARRAY['Use this construction to express A particle which, with a preceding noun phrase, forms a phrase to modify a following noun phrase.. A particle which, with a preceding noun phrase, forms a phrase to modify a following noun phrase.']::text[],ARRAY['【Related Expression: の2】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"これは先生の本だ・です。","japanese_furigana":"これは先生の本だ・です。","english":"This is my teacher''s book."},{"japanese":"これは友達からの手紙だ・です。","japanese_furigana":"これは友達からの手紙だ・です。","english":"This is a letter from my friend."}]'::jsonb),
    ('c4091543-1ddd-481b-9f73-b5af13a2a43b'::uuid,ARRAY['(i) {V/Adjectiveい}informal のなんのって']::text[],ARRAY['Use this construction to express A phrase to emphasize that something/someone is/was in an extreme state or that someone does/did something to a great extent. A phrase to emphasize that something/someone is/was in an extreme state or that someone does/did something to a great extent']::text[],ARRAY['【Related Expression: の~ないのって; なんてもんじゃない; などと言うものではない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"甘いのなんのって私は一口食べて全部残してしまいました。","japanese_furigana":"甘いのなんのって私は一口食べて全部残してしまいました。","english":"It was so sweet that I ate one bite and left the rest."},{"japanese":"飲んだのなんのって彼らは5本の酒を全部空けてしまった。","japanese_furigana":"飲んだのなんのって彼らは5本の酒を全部空けてしまった。","english":"They drank so much; they completely emptied ﬁve bottles of sake."}]'::jsonb),
    ('e79cbed9-bd3b-4e4e-a695-237ad0da8e4c'::uuid,ARRAY['Vinformal nonpast のに']::text[],ARRAY['Use this construction to express In the process or for the purpose of doing something expressed in the の nominalised clause.. In the process or for the purpose of doing something expressed in the の nominalised clause.']::text[],ARRAY['【Related Expression: に5; 為(に)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は日本語の新聞を読むのに辞書を使う・使います。","japanese_furigana":"私は日本語の新聞を読むのに辞書を使う・使います。","english":"I used a dictionary to read Japanese newspapers."},{"japanese":"すき焼きを作るのには何が要りますか。","japanese_furigana":"すき焼きを作るのには何が要りますか。","english":"What do you need to make sukiyaki?"}]'::jsonb),
    ('6026f814-0214-4361-ae12-2754bfd9894f'::uuid,ARRAY['(i) {V/Adjective い} informal のは～だ']::text[],ARRAY['Use this construction to express A structure that indicates new, important information by placing it between [x] and the copula [x] ([x] is an indefinite pronoun ([x]2) that replaces ‘time’,’person’, ‘thing’, ‘place’ or ‘reason’.). A structure that indicates new, important information by placing it between [x] and the copula [x] ([x] is an indefinite pronoun ([x]2) that replaces ‘time’,’person’, ‘thing’, ‘place’ or ‘reason’.)']::text[],ARRAY['【Related Expression: の3】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私が中国に行ったのは三年前だ・です。","japanese_furigana":"私が中国に行ったのは三年前だ・です。","english":"It was three years ago that I went to China. / The time when I went to China was three years ago."},{"japanese":"このクラスで一番頭がいいのは吉田さんだ・です。","japanese_furigana":"このクラスで一番頭がいいのは吉田さんだ・です。","english":"The brightest one in this class is Mr. Yoshida."}]'::jsonb),
    ('79045f4d-05ad-41ff-888f-61f47ccb6879'::uuid,ARRAY['Sinformal のは Noun のことだ (the same formation as のだ)']::text[],ARRAY['Use this construction to express A structure which focuses on a time when something takes place.. A structure which focuses on a time when something takes place.']::text[],ARRAY['The core sense is A structure which focuses on a time when something takes place.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"吉田さんと最後に会ったのは１９８５年の五月のことだ。","japanese_furigana":"吉田さんと最後に会ったのは１９８５年の五月のことだ。","english":"It was in May 1985 that I last met Mr. Yamada."},{"japanese":"日本語の面白さが分かり始めたのはごく最近のことだ。","japanese_furigana":"日本語の面白さが分かり始めたのはごく最近のことだ。","english":"It was only recently that I began to understand how interesting Japanese is."}]'::jsonb),
    ('de6f02c4-9dde-45d5-9a42-b2d0df738940'::uuid,ARRAY['(i) Noun のみ (Particle)']::text[],ARRAY['Use this construction to express A particle which expresses a limit imposed upon an action, event, or a state.. A particle which expresses a limit imposed upon an action, event, or a state.']::text[],ARRAY['【Related Expression: だけ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"要点のみ（を）話して下さい。","japanese_furigana":"要点のみ（を）話して下さい。","english":"Please tell me just the main point."},{"japanese":"これは吉田先生にのみ話してあります。","japanese_furigana":"これは吉田先生にのみ話してあります。","english":"I have told this only to Professor Yoshida."}]'::jsonb),
    ('a60e41d0-91d4-4812-8494-372fe869c56f'::uuid,ARRAY['(i) Noun (Particle) のみならず']::text[],ARRAY['Use this construction to express A phrase that is used in formal writing to mean “not only”.. A phrase that is used in formal writing to mean “not only”.']::text[],ARRAY['【Related Expression: だけで(は)なく; に限らず; にとどまらず; はおろか】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"我が社は日本国内のみならず、アメリカやヨーロッパなどでもビジネス活動を行っております。","japanese_furigana":"我が社は日本国内のみならず、アメリカやヨーロッパなどでもビジネス活動を行っております。","english":"Our company does business not only in Japan but also in America, Europe, and elsewhere."},{"japanese":"これからの企業は単に利益を追求するのみならず、環境に配慮した生産活動を行わなければならない。","japanese_furigana":"これからの企業は単に利益を追求するのみならず、環境に配慮した生産活動を行わなければならない。","english":"Today''s companies should not just pursue profits; they should also consider environmental protection issues in their production activities. (literally: they must perform production activities that take the environment into consideration as well.)"}]'::jsonb),
    ('c9d75736-0ac9-4670-8c3e-3a4a3c591244'::uuid,ARRAY['Noun の無さ']::text[],ARRAY['Use this construction to express A phrase that indicates a state where something is lacking.. A phrase that indicates a state where something is lacking.']::text[],ARRAY['The core sense is A phrase that indicates a state where something is lacking.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私は彼の常識の無さにあきれている。","japanese_furigana":"私は彼の常識の無さにあきれている。","english":"I am appalled by his lack of common sense."},{"japanese":"跳びたいと思っても跳べない。体力、筋力の無さを痛感しました。","japanese_furigana":"跳びたいと思っても跳べない。体力、筋力の無さを痛感しました。","english":"I wanted to jump, but I couldn''t. I became painfully aware of my lack of physical and muscular strength."}]'::jsonb),
    ('7ea355c9-8839-4803-ab19-9c5165318f8e'::uuid,ARRAY['Noun の関係で']::text[],ARRAY['Use this construction to express A phrase indicating that something takes place or does not take place because of something.. A phrase indicating that something takes place or does not take place because of something.']::text[],ARRAY['【Related Expression: の為(に)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ホールさんは今仕事の関係で東京に行っています。","japanese_furigana":"ホールさんは今仕事の関係で東京に行っています。","english":"Mr. Hall has gone to Tokyo on a business-related matter."},{"japanese":"鈴木は単位の関係で今年は卒業出来ないそうだ。","japanese_furigana":"鈴木は単位の関係で今年は卒業出来ないそうだ。","english":"I heard that Suzuki cannot graduate this year because of insufficient credits / units."}]'::jsonb),
    ('afef6379-c3f9-4295-ba8f-083830571b34'::uuid,ARRAY['(i) Vます は {する(が)/しない}']::text[],ARRAY['Use this construction to express A particle which emphatically affirms or negates the proposition represented by the preceding verbal and other related elements.. A particle which emphatically affirms or negates the proposition represented by the preceding verbal and other related elements.']::text[],ARRAY['【Related Expression: ことは】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"行きはしますが、何も手伝えませんよ。","japanese_furigana":"行きはしますが、何も手伝えませんよ。","english":"I am going (there) but I cannot help you, all right?"},{"japanese":"疲れてはいるが、まだ休みたくない。","japanese_furigana":"疲れてはいるが、まだ休みたくない。","english":"I am tired but I don''t want to take a break yet."}]'::jsonb),
    ('39cf0cb6-145f-455a-8995-6f0a9ce59cdd'::uuid,ARRAY['Noun はあれ']::text[],ARRAY['Use this construction to express A phrase expressing the idea “even though there is something”. A phrase expressing the idea “even though there is something”']::text[],ARRAY['【Related Expression: はあっても】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"インターフェースに若干の違いはあれ、この二つのプログラムは機能的には全く変わらない。","japanese_furigana":"インターフェースに若干の違いはあれ、この二つのプログラムは機能的には全く変わらない。","english":"Although their interfaces are slightly different, these two programs are just the same in terms of their functions."},{"japanese":"歴史の違いはあれ、米国には１２０万を越す非営利団体(NPO)が存在します。","japanese_furigana":"歴史の違いはあれ、米国には１２０万を越す非営利団体(NPO)が存在します。","english":"Although their histories are different (literally: there are differences in their histories), there are more than 1,200,000 non-profit organizations in America."}]'::jsonb),
    ('d9ff78b0-1f62-4559-ac3d-f5e96cf286a8'::uuid,ARRAY['(i) Noun はいいとしても']::text[],ARRAY['Use this construction to express A phrase that conveys the meaning “even if I/we accept something, something else is not acceptable”.. A phrase that conveys the meaning “even if I/we accept something, something else is not acceptable”.']::text[],ARRAY['【Related Expression: は仕方がないとしても】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"友達を助けようという動機はいいとしてもやり方が間違っている。","japanese_furigana":"友達を助けようという動機はいいとしてもやり方が間違っている。","english":"Your motivation for helping your friend is all right, but your way (of doing it) is wrong."},{"japanese":"私はいいとしても他の人がこの部屋では満足しないだろう。","japanese_furigana":"私はいいとしても他の人がこの部屋では満足しないだろう。","english":"Even if I accept it, other people wouldn''t be satisﬁed with this room."}]'::jsonb),
    ('8ffd82a7-689b-4c62-a27d-26077c5557f6'::uuid,ARRAY['Vて はいけない']::text[],ARRAY['Use this construction to express A phrase which indicates prohibition.. A phrase which indicates prohibition.']::text[],ARRAY['【Related Expression: はならない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この部屋に入ってはいけない・いけません。","japanese_furigana":"この部屋に入ってはいけない・いけません。","english":"You must not enter this room."},{"japanese":"教室でものを食べてはいけません。","japanese_furigana":"教室でものを食べてはいけません。","english":"You must not eat (food) in the classroom."}]'::jsonb),
    ('59fc5d1f-aaef-4eff-ac77-281a68e8c245'::uuid,ARRAY['Noun 1 はおろか Noun 2 {も/でも/さえ/すら/まで}']::text[],ARRAY['Use this construction to express A phrase that is used when something is not only true with one thing or person, but also with another thing or person that is less expected or understandable.. A phrase that is used when something is not only true with one thing or person, but also with another thing or person that is less expected or understandable.']::text[],ARRAY['【Related Expression: は言うまでもなく; は言うに及ばず; はもちろん; だけでなく; のみならず】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"インターネットはおろか、パソコンも触ってことがないのだが、講習会についていけるだろうか。","japanese_furigana":"インターネットはおろか、パソコンも触ってことがないのだが、講習会についていけるだろうか。","english":"Never having touched a computer, let alone used the Internet, I wonder if I will be able to keep up in the workshop."},{"japanese":"最近は大学生はおろか、中学生でもかなりの者が海外旅行を経験している。","japanese_furigana":"最近は大学生はおろか、中学生でもかなりの者が海外旅行を経験している。","english":"Never mind college students, these days even junior and senior high school students often have experienced traveling abroad."}]'::jsonb),
    ('99b8d05d-2cf6-434f-a915-e37d03766d04'::uuid,ARRAY['(i) Vinformal nonpast ばかり']::text[],ARRAY['Use this construction to express A particle which indicates that something is the only thing or state which exists, or the action someone will take, takes, is taking or took.. A particle which indicates that something is the only thing or state which exists, or the action someone will take, takes, is taking or took.']::text[],ARRAY['【Related Expression: ほど(くらい); しか (だけ); とろこだ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"デザートは食べるばかりになっている・います。","japanese_furigana":"デザートは食べるばかりになっている・います。","english":"The only thing left to do with the dessert is to eat it./The dessert is ready to eat."},{"japanese":"友子は遊んでばかりいる・います。","japanese_furigana":"友子は遊んでばかりいる・います。","english":"The only thing Tomoko is doing is playing./Tomoko is doing nothing but playing."}]'::jsonb),
    ('e78894fa-adc2-4b81-bb70-d817118b1aa8'::uuid,ARRAY['(i) {V/ Adjective い} informal ばかりか']::text[],ARRAY['Use this construction to express A compound particle/conjunction which is used to connect two nouns or two sentences, the first of which is something normally expected and the second of which is something normally unexpected.. A compound particle/conjunction which is used to connect two nouns or two sentences, the first of which is something normally expected and the second of which is something normally unexpected.']::text[],ARRAY['【Related Expression: ばかりで(は)なく~も; だけで(は)なく~も; どころか】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本では子供ばかりか大人さえ漫画を読んでいる。","japanese_furigana":"日本では子供ばかりか大人さえ漫画を読んでいる。","english":"In Japan not only children but even adults are reading comic books."},{"japanese":"あの人は絵を見て楽しむばかりか、自分でも絵を描く。","japanese_furigana":"あの人は絵を見て楽しむばかりか、自分でも絵を描く。","english":"He not only enjoys looking at pictures; he also draws them."}]'::jsonb),
    ('66d550e6-b174-4274-b4ba-8953d9cc7a06'::uuid,ARRAY['(i) NP は別として']::text[],ARRAY['Use this construction to express A phrase used to present an exception or an issue the speaker/writer does not intend to cover as part of a larger statement.. A phrase used to present an exception or an issue the speaker/writer does not intend to cover as part of a larger statement.']::text[],ARRAY['【Related Expression: を覗いて; 以外は; はさておき】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"特殊な場合は別として、手書きのレポートを書くことは少なくなった。","japanese_furigana":"特殊な場合は別として、手書きのレポートを書くことは少なくなった。","english":"Except for special cases, there are only a few occasions now in which we write hand-written reports."},{"japanese":"実施できるか(どうか)は別として、まず可能な解決策をすべてリストアップしてみよう。","japanese_furigana":"実施できるか(どうか)は別として、まず可能な解決策をすべてリストアップしてみよう。","english":"Putting aside the question of whether or not each one is feasible for us to carry out, let''s list all possible solutions ﬁrst."}]'::jsonb),
    ('db6b93c1-a6e2-49c1-a673-0ac807ac951d'::uuid,ARRAY['Canonical pattern: 〜へ']::text[],ARRAY['Use this construction to express A particle that indicates the direction toward which some directional movement or action proceeds.. A particle that indicates the direction toward which some directional movement or action proceeds.']::text[],ARRAY['【Related Expression: まで; に4; に7】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は先週京都へ旅行に行った・行きました。","japanese_furigana":"私は先週京都へ旅行に行った・行きました。","english":"I went on a trip to Kyoto last week."},{"japanese":"私は札幌のうちへ飛行機で帰った。","japanese_furigana":"私は札幌のうちへ飛行機で帰った。","english":"I went back home to Sapporo by plane."}]'::jsonb),
    ('241843b7-56ce-4c34-a0ba-2fd86adf9812'::uuid,ARRAY['(i) Vinformal nonpast べからず Exception: する→{す/する}べからず']::text[],ARRAY['Use this construction to express An auxiliary verb that indicates a strong prohibition.. An auxiliary verb that indicates a strong prohibition.']::text[],ARRAY['【Related Expression: Verb informal nonpast な; を禁ず(る); 禁止; てはいけません; ないで下さい; ないようにして下さい】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"芝生に入るべからず。","japanese_furigana":"芝生に入るべからず。","english":"Keep off the lawn. (literally: Don''t enter the lawn.)"},{"japanese":"原子力はエネルギー源として欠くべからざるものとなっている。","japanese_furigana":"原子力はエネルギー源として欠くべからざるものとなっている。","english":"Atomic energy has become indispensable as a source of energy."}]'::jsonb),
    ('0980c029-3de8-4410-89b2-7c2b57c474b0'::uuid,ARRAY['(i) Vinformal nonpast べきだ']::text[],ARRAY['Use this construction to express An auxiliary which expresses the speaker''s judgment that someone/something should do something or should be in some state.. An auxiliary which expresses the speaker''s judgment that someone/something should do something or should be in some state.']::text[],ARRAY['【Related Expression: はず; 方がいい; ものだ; なければならない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この論文は書き直すべきだ。","japanese_furigana":"この論文は書き直すべきだ。","english":"This thesis should be rewritten."},{"japanese":"そんなことを人に言うべき{では/じゃ}ありません。","japanese_furigana":"そんなことを人に言うべき{では/じゃ}ありません。","english":"You shouldn''t say that kind of thing to people."}]'::jsonb),
    ('6f72ab19-502f-4849-9150-af3cde2dec38'::uuid,ARRAY['V1informal nonpast べくして V2 (where V1=V2) Exception: する→{す/する}べくして']::text[],ARRAY['Use this construction to express A phrase used when something occurs/occured exactly as expected. A phrase used when something occurs/occured exactly as expected']::text[],ARRAY['【Related Expression: やはり/やっぱり】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"第二次世界大戦は起こるべくして起こった。","japanese_furigana":"第二次世界大戦は起こるべくして起こった。","english":"World War II occurred, exactly as expected."},{"japanese":"彼は大統領になるべくしてなった。","japanese_furigana":"彼は大統領になるべくしてなった。","english":"He became president, exactly as expected."}]'::jsonb),
    ('cf6b495e-1ced-4ca3-bd81-c6bc3ea0ce75'::uuid,ARRAY['Vinformal nonpast べくもない する→{す/する}べくもない']::text[],ARRAY['Use this construction to express A phrase meaning “it is impossible to do something”. A phrase meaning “it is impossible to do something”']::text[],ARRAY['【Related Expression: Verb potential わけがない; Verb potential はずがない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私が一億円の家を買うなど、望むべくもない。","japanese_furigana":"私が一億円の家を買うなど、望むべくもない。","english":"It is impossible for me to hope to buy a hundred million yen house."},{"japanese":"十年前に別れた女性の居どころなど知るべくもない。","japanese_furigana":"十年前に別れた女性の居どころなど知るべくもない。","english":"There is no way for me to know the whereabouts of the woman I split up with 10 years ago."}]'::jsonb),
    ('faf76bbf-01ee-470d-b2ae-a377466289ef'::uuid,ARRAY['(i) Vinformal nonpast まい']::text[],ARRAY['Use this construction to express An auxiliary which expresses the speaker''s negative volition or conjecture.. An auxiliary which expresses the speaker''s negative volition or conjecture.']::text[],ARRAY['The core sense is An auxiliary which expresses the speaker''s negative volition or conjecture.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"もう橋本には何も頼むまい。","japanese_furigana":"もう橋本には何も頼むまい。","english":"I will not ask any more favours of Hashimoto."},{"japanese":"これは恐らく誰も気が付くまい。","japanese_furigana":"これは恐らく誰も気が付くまい。","english":"Probably no one will notice this."}]'::jsonb),
    ('7124e7b5-6178-4628-ad4f-0d727378ed97'::uuid,ARRAY['Canonical pattern: 〜ましだ']::text[],ARRAY['Use this construction to express A phrase indicating that although someone/something (or some situation) is not satisfactory it is better than someone/something else.. A phrase indicating that although someone/something (or some situation) is not satisfactory it is better than someone/something else.']::text[],ARRAY['【Related Expression: いい】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"こんな給料をもらう（くらい）なら辞めた方がましだ。","japanese_furigana":"こんな給料をもらう（くらい）なら辞めた方がましだ。","english":"If this is the salary, it would be better to quit."},{"japanese":"今度の日本語の先生は前の先生よりずっとましだ。","japanese_furigana":"今度の日本語の先生は前の先生よりずっとましだ。","english":"This new Japanese teacher is much better than the former teacher."}]'::jsonb),
    ('6659e3de-f18e-42c4-abef-16f390948078'::uuid,ARRAY['Vinformal まで(のこと)だ']::text[],ARRAY['Use this construction to express A phrase indicating someone’s decision to cope with a negative situation, or a simple, straight forward reason for his/her action.. A phrase indicating someone’s decision to cope with a negative situation, or a simple, straight forward reason for his/her action.']::text[],ARRAY['【Related Expression: だから(のこと)だ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"もしTOEFLの点が悪かったらもう一度受けるまで（のこと）だ。","japanese_furigana":"もしTOEFLの点が悪かったらもう一度受けるまで（のこと）だ。","english":"If my TOEFL score isn''t good, then I''ll just take the test again."},{"japanese":"日本語は面白そうだったので、取ったまで（このと）だ。","japanese_furigana":"日本語は面白そうだったので、取ったまで（このと）だ。","english":"I took Japanese language only because it looked interesting (not for any other reason)."}]'::jsonb),
    ('d562820b-72d8-413a-b4b5-80fd0dc5e4de'::uuid,ARRAY['Number+Counter も Vconditional']::text[],ARRAY['Use this construction to express A structure which expresses the idea that a certain amount of something is sufficient to do something.. A structure which expresses the idea that a certain amount of something is sufficient to do something.']::text[],ARRAY['The core sense is A structure which expresses the idea that a certain amount of something is sufficient to do something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"この美術館は三時間もあれば全部見られる。","japanese_furigana":"この美術館は三時間もあれば全部見られる。","english":"Three hours are enough to see everything in this art museum. (literally: If you have as many as three hours, you can see everything in this art museum.)"},{"japanese":"二万円も持って行けば足りるでしょう。","japanese_furigana":"二万円も持って行けば足りるでしょう。","english":"20,000 yen will probably be enough. (literally: If you take as much as 20,000 yen with you, it will probably be sufficient.)"}]'::jsonb),
    ('48584d64-a377-44f2-87ee-110cee809d41'::uuid,ARRAY['(i) V1ます も すれ ば V2ます も する']::text[],ARRAY['Use this construction to express A structure used to present typical examples of actions, events, situations, people, or things among a number of possibilities.. A structure used to present typical examples of actions, events, situations, people, or things among a number of possibilities.']::text[],ARRAY['【Related Expression: も[Verb]し~も[Verb]; たり~たりする】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"父は感情的な人ではないが、時に怒りもすれば泣きもする。","japanese_furigana":"父は感情的な人ではないが、時に怒りもすれば泣きもする。","english":"My father is not an emotional person, but there are times when he gets angry and times when he cries."},{"japanese":"私だってロックも聞けばダンスもする。","japanese_furigana":"私だってロックも聞けばダンスもする。","english":"Even I sometimes (do things like) listen to rock music and dance."}]'::jsonb),
    ('113538cd-81ba-4f7b-a100-dd8c53c572ae'::uuid,ARRAY['NP もさることながら']::text[],ARRAY['Use this construction to express A phrase used to mention something important and then introduce something more signiﬁcant.. A phrase used to mention something important and then introduce something more signiﬁcant.']::text[],ARRAY['The core sense is A phrase used to mention something important and then introduce something more signiﬁcant.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"この図書館は蔵書の多さもさることながらサービスが実にすばらしい。","japanese_furigana":"この図書館は蔵書の多さもさることながらサービスが実にすばらしい。","english":"This library''s large collection of books is one thing (literally: is so, too), but the services they provide are really something else (literally: really wonderful)."},{"japanese":"指圧やマッサージといった「タッチセラピー」が注目されている。身体への直接的な効果もさることながら、安らぎ感や癒しといった心理的な効果も大きいようだ。","japanese_furigana":"指圧やマッサージといった「タッチセラピー」が注目されている。身体への直接的な効果もさることながら、安らぎ感や癒しといった心理的な効果も大きいようだ。","english":"“Touch therapies,” such as shiatsu and massage, are drawing people''s attention. While they have a direct effect on the body (literally: Their direct effect is so, too), apparently their psychological effect, including feelings of relaxation and healing, is also great."}]'::jsonb),
    ('4a61e133-174c-486f-8fd9-567ccee38e5a'::uuid,ARRAY['(i) {V/Adjectiveい}informal nonpast ものか']::text[],ARRAY['Use this construction to express A rhetorical question marker that expresses a strong negative intention or disagreement.. A rhetorical question marker that expresses a strong negative intention or disagreement.']::text[],ARRAY['The core sense is A rhetorical question marker that expresses a strong negative intention or disagreement.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"あんなやつとは二度と会うものか。","japanese_furigana":"あんなやつとは二度と会うものか。","english":"I will never see that sort of guy again."},{"japanese":"A:彼は5年後には自分でコンピュータの会社をつくるって言っているよ。 B:そんなこと彼にできるもんか。","japanese_furigana":"A:彼は5年後には自分でコンピュータの会社をつくるって言っているよ。 B:そんなこと彼にできるもんか。","english":"A: He says he will establish a computer company by himself in five years. B: I bet he can''t. (literally: Can he do it?)"}]'::jsonb),
    ('c8cfd628-3f4d-4c4d-8800-9c5513707bbd'::uuid,ARRAY['(i) Vpotential negativeない もの (だろう) か']::text[],ARRAY['Use this construction to express A phrase indicating that the speaker wants to do something or is wondering what one he/she should choose.. A phrase indicating that the speaker wants to do something or is wondering what one he/she should choose.']::text[],ARRAY['【Related Expression: たらいいのに; たらいいのだが; たらいいか; べきか】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"もう少し広い家に住めないもの（だろう）か。","japanese_furigana":"もう少し広い家に住めないもの（だろう）か。","english":"(i) I wish to live in a house that is a bit more spacious. (ii) I wonder if I can live in a slightly more spacious house."},{"japanese":"修士論文の題目をどのように決めたものか（と）迷っています。","japanese_furigana":"修士論文の題目をどのように決めたものか（と）迷っています。","english":"I am at a loss as to how I should choose my MA thesis topic."}]'::jsonb),
    ('bbbb1c30-bb58-44ae-94c0-c21e4afa378c'::uuid,ARRAY['(i) X やら Y やら']::text[],ARRAY['Use this construction to express A structure to present things, events, actions, etc., as examples, reasons or possibilities.. A structure to present things, events, actions, etc., as examples, reasons or possibilities.']::text[],ARRAY['【Related Expression: や~や; とか~とか; たり~たり; か~か; わ~わ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は会議やら講習会やらでこのところ出張が続いている。","japanese_furigana":"私は会議やら講習会やらでこのところ出張が続いている。","english":"I have been traveling for business a lot these days to conferences, workshops, etc."},{"japanese":"みんなに自分の写真をほめられて嬉しいやら恥ずかしいやら(で)変な気持ちでした。","japanese_furigana":"みんなに自分の写真をほめられて嬉しいやら恥ずかしいやら(で)変な気持ちでした。","english":"When people praised the picture of me I felt strange, both happy and shy."}]'::jsonb),
    ('3643d29a-236f-4d63-a155-7db3978e2f80'::uuid,ARRAY['(i) Vvolitional V: non-controllable verb']::text[],ARRAY['Use this construction to express An auxiliary verb that expresses the writer''s conjecture about some potentiality or his certainty about a given state of affairs.. An auxiliary verb that expresses the writer''s conjecture about some potentiality or his certainty about a given state of affairs.']::text[],ARRAY['【Related Expression: だろう; でしょう】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この程度の文章なら日本語の一年生でも読めよう。","japanese_furigana":"この程度の文章なら日本語の一年生でも読めよう。","english":"Even the first year students of Japanese (probably) can read a passage of this level."},{"japanese":"こんな寒い日にオーバーも着ないで歩き回れば、風邪も引こう。","japanese_furigana":"こんな寒い日にオーバーも着ないで歩き回れば、風邪も引こう。","english":"If you walk around without wearing an overcoat on such a cold day, it is a matter of course that you will catch a cold."}]'::jsonb),
    ('ae9fbffa-09be-4bdd-b4e5-8f7e2ae12d55'::uuid,ARRAY['Vます よう']::text[],ARRAY['Use this construction to express A noun forming suffix which means a way (of doing something).. A noun forming suffix which means a way (of doing something).']::text[],ARRAY['【Related Expression: 方】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この作文は直しようがない。","japanese_furigana":"この作文は直しようがない。","english":"There is no way to correct this composition."},{"japanese":"この成績じゃ・では救いようがない。","japanese_furigana":"この成績じゃ・では救いようがない。","english":"There is no way to save (him) with this grade."}]'::jsonb),
    ('71cc823b-e002-444f-8de8-62dd5ba6357f'::uuid,ARRAY['(i) Vvolitional { と / が }']::text[],ARRAY['Use this construction to express A conjunctive phrase that expresses the idea of concession.. A conjunctive phrase that expresses the idea of concession.']::text[],ARRAY['【Related Expression: ても; ようとも】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"人が何と言おう{と/が}、私は自分の子供を信じている。","japanese_furigana":"人が何と言おう{と/が}、私は自分の子供を信じている。","english":"Whatever (other) people say, I believe my child."},{"japanese":"頑固と言われよう{と/が}馬鹿と言われよう{と/が}、私は自分の信じることをやります。","japanese_furigana":"頑固と言われよう{と/が}馬鹿と言われよう{と/が}、私は自分の信じることをやります。","english":"Even if people say I''m stubborn or stupid, I''ll do what I believe."}]'::jsonb),
    ('1b2c51d0-910e-4129-9ced-baf33f8f303e'::uuid,ARRAY['(i) {V/Adjective い} informal ように']::text[],ARRAY['Use this construction to express An adverbial form of ようだ. An adverbial form of ようだ']::text[],ARRAY['The core sense is An adverbial form of ようだ; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私が言うように書いて下さい。","japanese_furigana":"私が言うように書いて下さい。","english":"Please write it down as I tell you."},{"japanese":"今日は春になったように暖かい・暖かいです。","japanese_furigana":"今日は春になったように暖かい・暖かいです。","english":"Today is as warm as if it had become spring."}]'::jsonb),
    ('9245db71-7d63-4344-84ef-9a8c0ec85b8f'::uuid,ARRAY['Vinformal nonpast {potential/ negative} ように']::text[],ARRAY['Use this construction to express Do something in such a way that ~.. Do something in such a way that ~.']::text[],ARRAY['The core sense is Do something in such a way that ~.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"読めるように字を奇麗に書いて下さい。","japanese_furigana":"読めるように字を奇麗に書いて下さい。","english":"Please write it neatly so that I can read it."},{"japanese":"風邪を引かないように気をつけている・います。","japanese_furigana":"風邪を引かないように気をつけている・います。","english":"I''m taking care of myself so that I don''t catch a cold."}]'::jsonb),
    ('d93c62b0-7889-4532-b382-b79523d6af7a'::uuid,ARRAY['Vvolitional にも (～ ない )']::text[],ARRAY['Use this construction to express A conjunctive phrase that indicates concession: “even though someone tries to do something, he/she cannot do it for some reason”.. A conjunctive phrase that indicates concession: “even though someone tries to do something, he/she cannot do it for some reason”.']::text[],ARRAY['【Related Expression: ようたって; にも; たくても(~ない); たくとも(~ない)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"徹に連絡しようにも電話番号もメールアドレスも知らない。","japanese_furigana":"徹に連絡しようにも電話番号もメールアドレスも知らない。","english":"Even though I want to contact Toru, I don''t know either her phone number or her e-mail address."},{"japanese":"ひどく頭が痛くて起きようにも起きられない。","japanese_furigana":"ひどく頭が痛くて起きようにも起きられない。","english":"I have a terrible headache, and I cannot get up even though I want to."}]'::jsonb),
    ('c422f456-7ea8-4d4a-ab08-5679f978a81e'::uuid,ARRAY['Vvolitional ものなら']::text[],ARRAY['Use this construction to express A conjunctive phrase that presents an undesirable hypothetical situation.. A conjunctive phrase that presents an undesirable hypothetical situation.']::text[],ARRAY['【Related Expression: たりしたら】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"山野氏は非常に時間に厳しい人で、面会時間に5分も遅れようものなら以後二度と会ってはもらえない。","japanese_furigana":"山野氏は非常に時間に厳しい人で、面会時間に5分も遅れようものなら以後二度と会ってはもらえない。","english":"Mr. Yamano is very strict about time; if you happen to be even five minutes late for an appointment with him, he won''t meet with you again."},{"japanese":"私はタバコの煙に特に敏感で、近くで吸われようものならもう何事にも集中できなくなってしまう。","japanese_furigana":"私はタバコの煙に特に敏感で、近くで吸われようものならもう何事にも集中できなくなってしまう。","english":"I''m particularly sensitive to cigarette smoke, so when someone is smoking nearby, I cannot concentrate on anything."}]'::jsonb),
    ('d3444b89-3892-4174-bbe3-4bc34a0ca52c'::uuid,ARRAY['(i) Vinformal nonpast ( より ) はか ( に )( は ) ない']::text[],ARRAY['Use this construction to express A phrase that conveys the idea that there is no other choice than to do something, or that something is true of only one of a select few things.. A phrase that conveys the idea that there is no other choice than to do something, or that something is true of only one of a select few things.']::text[],ARRAY['【Related Expression: なければならない; なければいけない; ざるを得ない; に~ない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"公共の交通機関がないので、自分の車で行く(より)ほか(に)(は)ない。","japanese_furigana":"公共の交通機関がないので、自分の車で行く(より)ほか(に)(は)ない。","english":"Since there is no public transportation, we have no other choice but to go there in your/my car."},{"japanese":"新聞はニューヨークタイムズのほか(に)は読まない。","japanese_furigana":"新聞はニューヨークタイムズのほか(に)は読まない。","english":"I read nothing but the New York Times. (literally: I don''t read any newspaper other than the New York Times.)"}]'::jsonb),
    ('ef0d662f-8334-4234-a3c9-09e06a529e1d'::uuid,ARRAY['Canonical pattern: 〜より（起点）']::text[],ARRAY['Use this construction to express A particle which indicates a set point in terms of space or time.. A particle which indicates a set point in terms of space or time.']::text[],ARRAY['【Related Expression: から1】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"メキシコは赤道より北にある・あります。","japanese_furigana":"メキシコは赤道より北にある・あります。","english":"Mexico is located north of the equator."},{"japanese":"この線より内側に入ってはいけません。","japanese_furigana":"この線より内側に入ってはいけません。","english":"You must not get inside this line."}]'::jsonb),
    ('3a984eba-c755-4633-9843-53d204522014'::uuid,ARRAY['(i) Group 1 verbs Vneg れる']::text[],ARRAY['Use this construction to express A state or an action cannot be controlled by someone or something.. A state or an action cannot be controlled by someone or something.']::text[],ARRAY['【Related Expression: お~になる; られる2】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"一郎は花子に騙された・騙されました。","japanese_furigana":"一郎は花子に騙された・騙されました。","english":"Ichiro was deceived by Hanako."},{"japanese":"ジェーンはフレッドに夜遅くアパートに来られた・来られました。","japanese_furigana":"ジェーンはフレッドに夜遅くアパートに来られた・来られました。","english":"Fred came to Jane''s apartment late at night (and Jane was unhappy)."}]'::jsonb),
    ('29243244-5223-4641-859a-27b6590b76f9'::uuid,ARRAY['ろくに Vnegative ない']::text[],ARRAY['Use this construction to express A structure that is used to indicate that something animate does not or cannot do something satisfactorily/sufficiently/properly.. A structure that is used to indicate that something animate does not or cannot do something satisfactorily/sufficiently/properly.']::text[],ARRAY['The core sense is A structure that is used to indicate that something animate does not or cannot do something satisfactorily/sufficiently/properly.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"飛行機の中ではろくに寝られなかった。","japanese_furigana":"飛行機の中ではろくに寝られなかった。","english":"On the plane I couldn''t sleep well."},{"japanese":"ろくに勉強もしないで試験を受けたので、全然出来なかった。","japanese_furigana":"ろくに勉強もしないで試験を受けたので、全然出来なかった。","english":"I took the exam without studying properly, so it was a disaster (literally: I couldn''t do well at all)."}]'::jsonb),
    ('e1ececbb-f86b-43ff-8da6-068a6783438c'::uuid,ARRAY['Canonical pattern: 〜わ']::text[],ARRAY['Use this construction to express A sentence final particle used in weak assertive or volitional sentences by a female speaker.. A sentence final particle used in weak assertive or volitional sentences by a female speaker.']::text[],ARRAY['The core sense is A sentence final particle used in weak assertive or volitional sentences by a female speaker.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私も明日のパーティーに行くわ。","japanese_furigana":"私も明日のパーティーに行くわ。","english":"I''ll go to tomorrow''s party, too."},{"japanese":"大木さんはもう帰りましたわ。","japanese_furigana":"大木さんはもう帰りましたわ。","english":"Mr. Ooki has already gone home."}]'::jsonb),
    ('c67c77ea-daed-4c93-8701-554bc414a4d1'::uuid,ARRAY['(i) S1informal nonpast わ S2informal nonpast わ']::text[],ARRAY['Use this construction to express A structure that emphatically presents actions, events or states as examples or reasons, or indicates that someone does something or something happens to a great extent.. A structure that emphatically presents actions, events or states as examples or reasons, or indicates that someone does something or something happens to a great extent.']::text[],ARRAY['【Related Expression: やら~やら】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"飛行機は12時間も遅れるわ荷物はなくなるわ(で)、今度の旅行は最悪だった。","japanese_furigana":"飛行機は12時間も遅れるわ荷物はなくなるわ(で)、今度の旅行は最悪だった。","english":"The ﬂight was delayed l2 hours, and my luggage was lost; this trip was the worst."},{"japanese":"客が来るわ来るわ、またたく間に小さい店はいっぱいになった。","japanese_furigana":"客が来るわ来るわ、またたく間に小さい店はいっぱいになった。","english":"Customers came in one after another, and in the blink of an eye, the small shop had ﬁlled up."}]'::jsonb),
    ('89b42307-8f47-412e-98f5-02236855188d'::uuid,ARRAY['(i) {V/Adjective い}informal nonpast わけがない']::text[],ARRAY['Use this construction to express A phrase which negates the existence of a reason to believe that someone does something or is in some state, or that something takes place; or which negates a possibility of someone''s doing something or being in some state, or something''s taking place.. A phrase which negates the existence of a reason to believe that someone does something or is in some state, or that something takes place; or which negates a possibility of someone''s doing something or being in some state, or something''s taking place.']::text[],ARRAY['【Related Expression: はずがない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"こんな易しい仕事が君に出来ないわけがない。","japanese_furigana":"こんな易しい仕事が君に出来ないわけがない。","english":"There is no reason why you cannot do such an easy job."},{"japanese":"日本語がそんなに速くマスター出来るわけがない。","japanese_furigana":"日本語がそんなに速くマスター出来るわけがない。","english":"It is impossible to be able to master Japanese that quickly."}]'::jsonb),
    ('8f23cdf1-9b0c-4323-99df-27590cd36559'::uuid,ARRAY['(i) {V/Adjective い} わけだ']::text[],ARRAY['Use this construction to express A phrase which presents a fact or truth known to the hearer as an introduction to a following statement, or which gives emphasis to a fact or truth which the hearer might not know.. A phrase which presents a fact or truth known to the hearer as an introduction to a following statement, or which gives emphasis to a fact or truth which the hearer might not know.']::text[],ARRAY['【Related Expression: のだ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"福田先生の死で私達はリーダーを失ってしまったわけですが、今後は私達自身でこの会を発展させていかなければなりません。","japanese_furigana":"福田先生の死で私達はリーダーを失ってしまったわけですが、今後は私達自身でこの会を発展させていかなければなりません。","english":"As you know, we lost our leader with Professor Fukuda''s death. From now on we have to advance this group by ourselves."},{"japanese":"戦争は大きな犠牲を伴うわけで、我々は何としてもこれを避けなければならない。","japanese_furigana":"戦争は大きな犠牲を伴うわけで、我々は何としてもこれを避けなければならない。","english":"War is accompanied by great sacrifice, as you know, and we have to avoid it at any cost."}]'::jsonb),
    ('adbe4ad1-c8d6-4c23-8969-1ed48d8ad663'::uuid,ARRAY['(i) {V/Adjective い} informal わけだ']::text[],ARRAY['Use this construction to express The speaker''s conclusion obtained through deductive, logical judgment or calculation on the basis of what he has heard or read.. The speaker''s conclusion obtained through deductive, logical judgment or calculation on the basis of what he has heard or read.']::text[],ARRAY['【Related Expression: はずだ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"毎日三時間も日本語を勉強いるんですか。よく出来るわけですね。","japanese_furigana":"毎日三時間も日本語を勉強いるんですか。よく出来るわけですね。","english":"Are you studying Japanese (as long as) three hours every day? No wonder your Japanese is good."},{"japanese":"明日試験ですか。じゃあ今晩忙しいわけですね。","japanese_furigana":"明日試験ですか。じゃあ今晩忙しいわけですね。","english":"Do you have an exam tomorrow? Then, you must be busy tonight."}]'::jsonb),
    ('113534ed-53b0-4d73-a965-8ad704f38bbc'::uuid,ARRAY['(i) {V/Adjective い}informal ( という ) わけではない']::text[],ARRAY['Use this construction to express A phrase which is used to deny what is implied in the previous or following statement.. Import a full grammar_guide JSON object to complete this canonical guide.']::text[],ARRAY['The core sense is A phrase which is used to deny what is implied in the previous or following statement.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"この問題を解決するのは非常に難しい。しかし、不可能（だ）というわけではない。","japanese_furigana":"この問題を解決するのは非常に難しい。しかし、不可能（だ）というわけではない。","english":"It is very difficult to solve this problem. But that does not mean that it is impossible (to solve)."},{"japanese":"君の考えに反対するわけではないが、そのやり方でうまくいくだろうか。","japanese_furigana":"君の考えに反対するわけではないが、そのやり方でうまくいくだろうか。","english":"I don''t mean to oppose your idea, but I wonder if things will go well using that approach."}]'::jsonb),
    ('b0e6840a-7b02-439b-81ed-cbf62802ded5'::uuid,ARRAY['(i) Vinformal nonpast わけにはいかない']::text[],ARRAY['Use this construction to express A phrase which is used to indicate that one cannot do something due to an external circumstance.. A phrase which is used to indicate that one cannot do something due to an external circumstance.']::text[],ARRAY['【Related Expression: ことが出来る; なければならない; られない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"来週は期末試験があるから、今週末は遊んでいるわけにはいかない。","japanese_furigana":"来週は期末試験があるから、今週末は遊んでいるわけにはいかない。","english":"There will be final examinations next week, so I cannot fool around this weekend."},{"japanese":"親友の結婚式だから、出席しないわけにはいかない。","japanese_furigana":"親友の結婚式だから、出席しないわけにはいかない。","english":"Since it is the wedding of my close friend I have no other choice but to attend it."}]'::jsonb),
    ('e0d1182b-3cc9-44a8-8487-1fdcc14ea6ae'::uuid,ARRAY['Canonical pattern: 〜を（感情の対象・原因）']::text[],ARRAY['Use this construction to express A particle that marks the cause of some human emotion.. A particle that marks the cause of some human emotion.']::text[],ARRAY['The core sense is A particle that marks the cause of some human emotion.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"次郎は父の死を悲しんだ・悲しみました。","japanese_furigana":"次郎は父の死を悲しんだ・悲しみました。","english":"Jiro was saddened at his father''s death."},{"japanese":"次郎は父が死んだこと・のを悲しんだ・悲しみした。","japanese_furigana":"次郎は父が死んだこと・のを悲しんだ・悲しみした。","english":"Jiro was sad that his father died."}]'::jsonb),
    ('e0625119-717f-4f37-8e20-04ac7ce8a607'::uuid,ARRAY['Canonical pattern: 〜を（目的語）']::text[],ARRAY['Use this construction to express A particle which marks a direct object.. A particle which marks a direct object.']::text[],ARRAY['The core sense is A particle which marks a direct object.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私は日本語を勉強している・います。","japanese_furigana":"私は日本語を勉強している・います。","english":"I''m studying Japanese."},{"japanese":"前田さんは昨日車を買った。","japanese_furigana":"前田さんは昨日車を買った。","english":"Mr. Maeda bought a car yesterday."}]'::jsonb),
    ('8d5f1b4d-71e0-4ad7-9c27-745e91ca9f2b'::uuid,ARRAY['Canonical pattern: 〜を（経路）']::text[],ARRAY['Use this construction to express A particle which indicates a space in/on/across/through/along which someone or something moves.. A particle which indicates a space in/on/across/through/along which someone or something moves.']::text[],ARRAY['【Related Expression: で1】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は五番街を歩いた・歩きました。","japanese_furigana":"私は五番街を歩いた・歩きました。","english":"I walked along Fifth Avenue."},{"japanese":"公園を通って帰りましょう。","japanese_furigana":"公園を通って帰りましょう。","english":"Let''s go home passing through the park."}]'::jsonb),
    ('10e8675c-f154-424d-b152-c3953ea8888e'::uuid,ARRAY['Canonical pattern: 〜を（起点）']::text[],ARRAY['Use this construction to express A particle that marks the location from which some movement begins.. A particle that marks the location from which some movement begins.']::text[],ARRAY['【Related Expression: から1】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は朝七時半に家を出る・出ます。","japanese_furigana":"私は朝七時半に家を出る・出ます。","english":"I leave home at 7.30 in the morning."},{"japanese":"汽車がトンネルを出た。","japanese_furigana":"汽車がトンネルを出た。","english":"A train came out of the tunnel."}]'::jsonb),
    ('cd9b3245-b6f0-44a8-b293-2bb10c252560'::uuid,ARRAY['Noun をおいてほかに ( は )～ ない']::text[],ARRAY['Use this construction to express A phrase that means “there is nothing else besides X”.. A phrase that means “there is nothing else besides X”.']::text[],ARRAY['【Related Expression: 以外に~ない; のほかに~ない; 一番; もっとも】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本語を短期間で習得したいのならこの学校をおいてほかに(は)ない。","japanese_furigana":"日本語を短期間で習得したいのならこの学校をおいてほかに(は)ない。","english":"If you want to learn Japanese in a short period of time, there is no other school (that you should consider) but this one."},{"japanese":"これほど多くの作品を手がけた監督はY氏をおいてほかにいない。","japanese_furigana":"これほど多くの作品を手がけた監督はY氏をおいてほかにいない。","english":"No other director has been involved with as many works as Mr. Y."}]'::jsonb),
    ('935fc466-906f-43b5-a025-9364a19baac3'::uuid,ARRAY['Noun をはじめ ( として )']::text[],ARRAY['Use this construction to express A phrase that is used to give a primary example.. A phrase that is used to give a primary example.']::text[],ARRAY['【Related Expression: だけで(は)なく~(も)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私のうちでは、父をはじめ（として）、家族全員スポーツが好きだ。","japanese_furigana":"私のうちでは、父をはじめ（として）、家族全員スポーツが好きだ。","english":"In my family, starting with my father, all of us like sports."},{"japanese":"キャシーは、寿司をはじめとして、日本食なら何でも食べる。","japanese_furigana":"キャシーは、寿司をはじめとして、日本食なら何でも食べる。","english":"Starting with sushi, Cathy eats any Japanese cuisine."}]'::jsonb),
    ('94398542-da41-4235-946a-d0f9d560cde9'::uuid,ARRAY['(i) Noun をめぐって']::text[],ARRAY['Use this construction to express A compound particle meaning “concerning; over”, which is used with an issue over which different opinions, ideas, etc., are expressed or exchanged.. A compound particle meaning “concerning; over”, which is used with an issue over which different opinions, ideas, etc., are expressed or exchanged.']::text[],ARRAY['【Related Expression: に関して; について】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"モノレール建設をめぐって市民の意見が対立している。","japanese_furigana":"モノレール建設をめぐって市民の意見が対立している。","english":"Citizens'' opinions are divided over the monorail construction."},{"japanese":"無駄な公共事業をめぐる批判の声が強まっている。","japanese_furigana":"無駄な公共事業をめぐる批判の声が強まっている。","english":"(Voices of) Criticism concerning wasteful public projects is growing stronger."}]'::jsonb),
    ('e5db0652-d107-4513-9f57-24e91dbe49fc'::uuid,ARRAY['(i) Noun をものともせず']::text[],ARRAY['Use this construction to express A phrase indicating that someone does something bravely/fearlessly in spite of unfavourable circumstances.. A phrase indicating that someone does something bravely/fearlessly in spite of unfavourable circumstances.']::text[],ARRAY['【Related Expression: にもかかわらず】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼女は重度の身体障害をものともせず、自分の人生をつかみとった。","japanese_furigana":"彼女は重度の身体障害をものともせず、自分の人生をつかみとった。","english":"Despite severe physical handicaps, she took charge of her own life."},{"japanese":"彼は日本語がしゃべれないのをものともせず、身振り手振りで日本を旅行して歩いた。","japanese_furigana":"彼は日本語がしゃべれないのをものともせず、身振り手振りで日本を旅行して歩いた。","english":"Undaunted by his inability to speak Japanese, he travelled around Japan communicating with gestures and signs."}]'::jsonb),
    ('5a13f0b7-65de-49b1-9a86-d6b9d06764eb'::uuid,ARRAY['(i) NP をよそに']::text[],ARRAY['Use this construction to express A compound particle that expresses someone’s indifference to warnings, criticism, advice, accusations, opposition, anxiety, wishes, eagerness, provocative actions, etc.. A compound particle that expresses someone’s indifference to warnings, criticism, advice, accusations, opposition, anxiety, wishes, eagerness, provocative actions, etc.']::text[],ARRAY['The core sense is A compound particle that expresses someone’s indifference to warnings, criticism, advice, accusations, opposition, anxiety, wishes, eagerness, provocative actions, etc.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"首相は国民の批判をよそにイラク戦争支持を表明した。","japanese_furigana":"首相は国民の批判をよそにイラク戦争支持を表明した。","english":"Setting aside people''s criticism, the prime minister declared his support for the Iraq War."},{"japanese":"青春時代、友達がデートに明け暮れるのをよそに、僕は家に一人こもってSFを読んでいた。","japanese_furigana":"青春時代、友達がデートに明け暮れるのをよそに、僕は家に一人こもってSFを読んでいた。","english":"During my adolescent years, I secluded myself at home and read science ﬁction, ignoring my friends, who were spending all their time dating."}]'::jsonb),
    ('945150c0-647e-4a63-8657-bd349cd36695'::uuid,ARRAY['Noun を中心に']::text[],ARRAY['Use this construction to express A phrase that means “with something/someone at the centre”.. A phrase that means “with something/someone at the centre”.']::text[],ARRAY['【Related Expression: を中心と/にして】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"東京を中心に大雨が降った。","japanese_furigana":"東京を中心に大雨が降った。","english":"There was heavy rain, mostly in and around Tokyo."},{"japanese":"東南アジアを中心に鳥インフルエンザが急速に広がっている。","japanese_furigana":"東南アジアを中心に鳥インフルエンザが急速に広がっている。","english":"Bird ﬂu is spreading rapidly, primarily in Southeast Asia."}]'::jsonb),
    ('c04f1dd6-ce65-4bb9-940b-39f305d9eeb8'::uuid,ARRAY['(i) Noun を介して']::text[],ARRAY['Use this construction to express A compound particle that introduces a medium through which someone does something or something happens to someone or something.. A compound particle that introduces a medium through which someone does something or something happens to someone or something.']::text[],ARRAY['【Related Expression: をとうして; によって/より】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"今、現地の代理人を介して製造元と価格の交渉をしている。","japanese_furigana":"今、現地の代理人を介して製造元と価格の交渉をしている。","english":"We are negotiating the price with the manufacturer through a local agent now."},{"japanese":"インターネットを介して音楽や映画を配信できるようになった。","japanese_furigana":"インターネットを介して音楽や映画を配信できるようになった。","english":"Music and movies can be distributed via the Internet now."}]'::jsonb),
    ('7cad911a-2795-4956-b439-6df7571d6de3'::uuid,ARRAY['(i) Noun 1 ({、/ と/や}Noun 2 ) を問わず']::text[],ARRAY['Use this construction to express A compound particle that means “without questioning”.. A compound particle that means “without questioning”.']::text[],ARRAY['【Related Expression: にかかわらず; に関係なく; によらず】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この会社は、経験があれば学歴を問わず採用してくれる。","japanese_furigana":"この会社は、経験があれば学歴を問わず採用してくれる。","english":"This company will employ you regardless of your educational background if you have (relevant work) experience."},{"japanese":"卒業後就職するか進学するかを問わず、担任との個人面談を受けなければならない。","japanese_furigana":"卒業後就職するか進学するかを問わず、担任との個人面談を受けなければならない。","english":"You have to have an individual consultation with your homeroom teacher whether you work or go on to college after graduation."}]'::jsonb),
    ('862c93e5-ffcf-4f5e-a80d-f8af9ab88673'::uuid,ARRAY['(i) Noun を禁じ得ない']::text[],ARRAY['Use this construction to express A phrase that is used when one cannot control emotions or reactions caused by emotions.. A phrase that is used when one cannot control emotions or reactions caused by emotions.']::text[],ARRAY['The core sense is A phrase that is used when one cannot control emotions or reactions caused by emotions.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"このような無責任な行いに対して怒りを禁じ得ない。","japanese_furigana":"このような無責任な行いに対して怒りを禁じ得ない。","english":"I cannot hold back my anger at such an irresponsible deed."},{"japanese":"その感動的な光景を見て、涙がこみ上げてくるのを禁じ得なかった。","japanese_furigana":"その感動的な光景を見て、涙がこみ上げてくるのを禁じ得なかった。","english":"Seeing the moving scene, I could not keep my tears from welling up."}]'::jsonb),
    ('2896e9a7-88fd-4a0f-bd0e-d2f6a89c5235'::uuid,ARRAY['Noun を通して']::text[],ARRAY['Use this construction to express A compound particle that is used to indicate a medium through which something is done or time through which something takes place.. A compound particle that is used to indicate a medium through which something is done or time through which something takes place.']::text[],ARRAY['【Related Expression: を通じて】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は親しい友達を通してそのピアニストと知り合いになった。","japanese_furigana":"私は親しい友達を通してそのピアニストと知り合いになった。","english":"I became acquainted with the pianist through a close friend of mine."},{"japanese":"私は一年を通して五回ぐらい海外に行っている。","japanese_furigana":"私は一年を通して五回ぐらい海外に行っている。","english":"I go abroad about 5 times a year (literally: throughout the year)."}]'::jsonb),
    ('70c1b246-2e45-40d9-936d-ea4d980e3965'::uuid,ARRAY['Vnegative んとする Exception:する→せんとする']::text[],ARRAY['Use this construction to express A phrase meaning for “someone to try to do something” or for “something to be about to occur”.. A phrase meaning for “someone to try to do something” or for “something to be about to occur”.']::text[],ARRAY['【Related Expression: ようとする】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"教授の言わんとすることが学生に伝わらないのは、たいてい教授の方が悪いのだ。","japanese_furigana":"教授の言わんとすることが学生に伝わらないのは、たいてい教授の方が悪いのだ。","english":"It is usually a professor who is to blame when his students don''t comprehend what he tries to convey."},{"japanese":"太陽はまさに山の稜線に沈まんとしていた。","japanese_furigana":"太陽はまさに山の稜線に沈まんとしていた。","english":"The sun was about to sink behind the mountain ridge."}]'::jsonb),
    ('360c544a-c465-4654-ae55-8995db9b1142'::uuid,ARRAY['一 [Counter] として ～ ない']::text[],ARRAY['Use this construction to express A structure that means “not a single one".. A structure that means “not a single one".']::text[],ARRAY['【Related Expression: {Interrogative word] ひと/いち [counter]~ない; ひと/いち [counter] たりとも~ない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"うちの課には一人として英語を話せる者がいない。","japanese_furigana":"うちの課には一人として英語を話せる者がいない。","english":"Not a single person in my section can speak English."},{"japanese":"この資料室には一冊として役に立つ本がない。","japanese_furigana":"この資料室には一冊として役に立つ本がない。","english":"There''s not a single useful book in this library."}]'::jsonb),
    ('69c7de25-4066-4f40-b52c-9375654e492d'::uuid,ARRAY['一切 Vnegative ない']::text[],ARRAY['Use this construction to express A structure that means “not at all”.. A structure that means “not at all”.']::text[],ARRAY['【Related Expression: 全然~ない; 全く~ない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"飛行機事故の原因は一切分からない。","japanese_furigana":"飛行機事故の原因は一切分からない。","english":"We have no idea what caused the airplane accident."},{"japanese":"この製品には遺伝子組み換え大豆は一切使用していません。","japanese_furigana":"この製品には遺伝子組み換え大豆は一切使用していません。","english":"For this product we haven''t used any genetically modiﬁed soybeans at all."}]'::jsonb),
    ('95919eea-0aca-44c7-a36a-2dfea3a7f76c'::uuid,ARRAY['(i) Vinformal nonpast 一方だ']::text[],ARRAY['Use this construction to express A phrase indicating that “something happens continuously” or “someone does something repeatedly”.. A phrase indicating that “something happens continuously” or “someone does something repeatedly”.']::text[],ARRAY['【Related Expression: ばかりだ; ますます; だけ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"物価は上げる一方だ。","japanese_furigana":"物価は上げる一方だ。","english":"(Commodity) prices are rising steadily."},{"japanese":"久子は私にものを頼む一方で、何もしてくれたことがない。","japanese_furigana":"久子は私にものを頼む一方で、何もしてくれたことがない。","english":"Hisako is always requesting favours but has never done anything for me."}]'::jsonb),
    ('e44b3967-31ac-4c0c-9f26-67a136ce56f7'::uuid,ARRAY['Nounは 一方では S1 Conjunction, 他方では S2']::text[],ARRAY['Use this construction to express A structure used to describe two concurring, contrastive actions/states of someone or something.. A structure used to describe two concurring, contrastive actions/states of someone or something.']::text[],ARRAY['The core sense is A structure used to describe two concurring, contrastive actions/states of someone or something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"神田先生は、一方では大学で物理学を教えながら、他方では日本語の研究をなさっている。","japanese_furigana":"神田先生は、一方では大学で物理学を教えながら、他方では日本語の研究をなさっている。","english":"Professor Kanda teaches physics at college on the one hand and does research on Japanese language on the other."},{"japanese":"あの男は、一方では静かな日本画を描いたりしているが、他方ではサッカーのような激しいスポーツをしている。","japanese_furigana":"あの男は、一方では静かな日本画を描いたりしているが、他方ではサッカーのような激しいスポーツをしている。","english":"That man draws quiet Japanese paintings on the one hand, but plays a very competitive sport like soccer on the other."}]'::jsonb),
    ('eedfd0f9-02a3-4f4a-b568-71b92a07fbf9'::uuid,ARRAY['Noun 上']::text[],ARRAY['Use this construction to express A suffix which indicates the idea of "from the viewpoint of," "for the sake of," "for the reason," or "in terms of".. A suffix which indicates the idea of "from the viewpoint of," "for the sake of," "for the reason," or "in terms of".']::text[],ARRAY['【Related Expression: の上では】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この映画は教育上よくない。","japanese_furigana":"この映画は教育上よくない。","english":"This film is not good from an educational point of view."},{"japanese":"便宜上私がこの部屋の鍵を預かっているんです。","japanese_furigana":"便宜上私がこの部屋の鍵を預かっているんです。","english":"I keep the key to this room for the sake of convenience."}]'::jsonb),
    ('afe10f92-2998-46a5-8828-406dfa31d2e8'::uuid,ARRAY['(i) Vて 下さい']::text[],ARRAY['Use this construction to express An auxiliary verb which indicates a polite request.. An auxiliary verb which indicates a polite request.']::text[],ARRAY['The core sense is An auxiliary verb which indicates a polite request.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"日本語で書いて下さい。","japanese_furigana":"日本語で書いて下さい。","english":"Please write in Japanese."},{"japanese":"英語を使わないで下さい。","japanese_furigana":"英語を使わないで下さい。","english":"Please don''t use English."}]'::jsonb),
    ('72c09fdb-dab7-4571-8970-c47432decaf5'::uuid,ARRAY['(i) Vinformal nonpast 中を']::text[],ARRAY['Use this construction to express A phrase that specifies space or time in/through which someone/something does something.. A phrase that specifies space or time in/through which someone/something does something.']::text[],ARRAY['【Related Expression: ところを; 時に】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"冷たい風が｛吹く/吹いている｝中を１０キロも歩いた。","japanese_furigana":"冷たい風が｛吹く/吹いている｝中を１０キロも歩いた。","english":"When a cold wind was blowing I walked as much as 10 kilometres."},{"japanese":"お忙しい中をいらしていただき、申し訳ございません。","japanese_furigana":"お忙しい中をいらしていただき、申し訳ございません。","english":"Thank you very much (literally: I''m sorry) for coming when you are (so) busy."}]'::jsonb),
    ('2a0224ab-2f73-48da-95c7-f11f106f7555'::uuid,ARRAY['(i) 何 Noun 1 ない Noun 2']::text[],ARRAY['Use this construction to express A structure indicating that something doesn''t exist at all.. A structure indicating that something doesn''t exist at all.']::text[],ARRAY['【Related Expression: 全く~ない; 全然~ない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼女は何不自由ない裕福な家庭で育った。","japanese_furigana":"彼女は何不自由ない裕福な家庭で育った。","english":"She grew up in a comfortable and rich family without inconveniences."},{"japanese":"マイケルは何問題なく日本での留学生活を続けている。","japanese_furigana":"マイケルは何問題なく日本での留学生活を続けている。","english":"Michael is continuing his study abroad in Japan without any problems."}]'::jsonb),
    ('f19373c6-3600-450d-bc23-bfee0984d25a'::uuid,ARRAY['(i) 何 (Number)+Counter も']::text[],ARRAY['Use this construction to express A phrase that indicates there is a large number of things, people, etc.. A phrase that indicates there is a large number of things, people, etc.']::text[],ARRAY['The core sense is A phrase that indicates there is a large number of things, people, etc.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私は日本へは何回も行ったことがあるが、韓国と中国はまだだ。","japanese_furigana":"私は日本へは何回も行ったことがあるが、韓国と中国はまだだ。","english":"I have been to Japan many times, but I''ve never been to Korea or China."},{"japanese":"私は日本語の辞書を何十冊も持っている。","japanese_furigana":"私は日本語の辞書を何十冊も持っている。","english":"I have dozens of Japanese dictionaries."}]'::jsonb),
    ('f1fc2410-1085-439f-b512-6eeca48bf421'::uuid,ARRAY['Canonical pattern: 〜何でも']::text[],ARRAY['Use this construction to express A phrase that indicates the speaker''s uncertainty about something.. A phrase that indicates the speaker''s uncertainty about something.']::text[],ARRAY['The core sense is A phrase that indicates the speaker''s uncertainty about something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"何でも山本さんは奥さんと別れて、一人で暮らしているそうですよ。","japanese_furigana":"何でも山本さんは奥さんと別れて、一人で暮らしているそうですよ。","english":"I don''t know for sure, but they say that Mr. Yamamoto has separated from his wife and lives alone."},{"japanese":"何でもこの辺は物価が非常に高いそうですよ。","japanese_furigana":"何でもこの辺は物価が非常に高いそうですよ。","english":"I don''t know for sure, but they say things are expensive in this neighbourhood."}]'::jsonb),
    ('0bfca46a-1b0f-401a-9422-ceb294e478b0'::uuid,ARRAY['何も ～ ない']::text[],ARRAY['Use this construction to express A structure indicating that an action is taken for no good reason.. A structure indicating that an action is taken for no good reason.']::text[],ARRAY['The core sense is A structure indicating that an action is taken for no good reason.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"何もそんなに怒ることはないよ。","japanese_furigana":"何もそんなに怒ることはないよ。","english":"You have no good reason to get so angry."},{"japanese":"良性の腫瘍だから、何もそんなに心配する必要はない。","japanese_furigana":"良性の腫瘍だから、何もそんなに心配する必要はない。","english":"It''s a benign tumour, so you don''t need to worry about it too much."}]'::jsonb),
    ('7ab30948-ac62-4677-a20a-054b306737c4'::uuid,ARRAY['(i) 何ら Noun {が/も} ない']::text[],ARRAY['Use this construction to express A structure that is used to express a strong negative statement.. A structure that is used to express a strong negative statement.']::text[],ARRAY['【Related Expression: 何も~ない; 少しも~ない; ちっとも~ない; 全然~ない; 全く~ない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本の大学教育の現状は何ら改善されていない。","japanese_furigana":"日本の大学教育の現状は何ら改善されていない。","english":"The state of Japanese college education has not improved at all."},{"japanese":"会社側は労働組合に対して何らの誠意ある回答もしなかった。","japanese_furigana":"会社側は労働組合に対して何らの誠意ある回答もしなかった。","english":"The company (literally: company side) has failed to give any sincere reply to the labour union (whatsoever)."}]'::jsonb),
    ('19854de5-2b3c-4389-abb8-cf09f85f4977'::uuid,ARRAY['何らかの Noun']::text[],ARRAY['Use this construction to express A phrase used to indicate that the exact nature of something represented by the noun cannot be speciﬁed.. A phrase used to indicate that the exact nature of something represented by the noun cannot be speciﬁed.']::text[],ARRAY['【Related Expression: なん(い)かの】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"何らかの原因で走行中で電車が急停車した。","japanese_furigana":"何らかの原因で走行中で電車が急停車した。","english":"Due to some (unknown) cause the train stopped suddenly."},{"japanese":"私たちが患う病気は、たいてい、何らかの意味でゲノム関係があります。","japanese_furigana":"私たちが患う病気は、たいてい、何らかの意味でゲノム関係があります。","english":"Most of the illnesses that we get are linked in some way with genomes."}]'::jsonb),
    ('140f5cb6-92c8-41e0-9303-ada3e653c9fe'::uuid,ARRAY['例の Noun']::text[],ARRAY['Use this construction to express A phrase which signals that the referent of the following noun phrase is definite and that the speaker expects the hearer to understand what the referent is.. A phrase which signals that the referent of the following noun phrase is definite and that the speaker expects the hearer to understand what the referent is.']::text[],ARRAY['【Related Expression: は】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"例のプロジェクトはどうなりましたか。","japanese_furigana":"例のプロジェクトはどうなりましたか。","english":"What happened to the project (in question)?"},{"japanese":"今年の忘年会はまた例の中華料理屋だそうだ。","japanese_furigana":"今年の忘年会はまた例の中華料理屋だそうだ。","english":"I heard that this year''s year-end party is going to be at that Chinese restaurant again."}]'::jsonb),
    ('04bc464e-4bf5-469d-a433-e53b5776ecb6'::uuid,ARRAY['(i) Number+Counter 分 ( の Noun)']::text[],ARRAY['Use this construction to express A suffix which indicates the amount of something.. A suffix which indicates the amount of something.']::text[],ARRAY['【Related Expression: 前】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ガソリンを十ドル分入れておきました。","japanese_furigana":"ガソリンを十ドル分入れておきました。","english":"I put in ten dollars worth of gas."},{"japanese":"私は今日三日分の仕事を片付けた。","japanese_furigana":"私は今日三日分の仕事を片付けた。","english":"Today I did three days worth of work."}]'::jsonb),
    ('54336cdf-130e-499b-984a-fa9b628d6467'::uuid,ARRAY['(i) Noun {の/である/だった/であった} 割に ( は )']::text[],ARRAY['Use this construction to express A phrase that expresses the idea that something is not in proportion to what one would normally expect.. A phrase that expresses the idea that something is not in proportion to what one would normally expect.']::text[],ARRAY['【Related Expression: にしては】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この店のサービスランチは値段の割に(は)おいしくボリュームがある。","japanese_furigana":"この店のサービスランチは値段の割に(は)おいしくボリュームがある。","english":"The bargain lunch at this restaurant is tasty and the portions are generous for the price."},{"japanese":"ビルはよく勉強している割に(は)成績が伸びない。","japanese_furigana":"ビルはよく勉強している割に(は)成績が伸びない。","english":"For all his hard work, Bill''s grades don''t seem to improve. / Although Bill studies hard, his grades do not improve."}]'::jsonb),
    ('c52bd16f-7451-4942-acbd-c83808f018c2'::uuid,ARRAY['(i) (Number+) Counter 単位で']::text[],ARRAY['Use this construction to express A phrase that indicates the smallest amount, number or unit of something (or people) involved.. A phrase that indicates the smallest amount, number or unit of something (or people) involved.']::text[],ARRAY['【Related Expression: ずつ; ごとに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"このATMは千円単位でお金を引き出すことができる。","japanese_furigana":"このATMは千円単位でお金を引き出すことができる。","english":"You can withdraw money from this ATM in multiples of 1,000 yen."},{"japanese":"この社内調査では課単位でリサイクル実施率を調べる。","japanese_furigana":"この社内調査では課単位でリサイクル実施率を調べる。","english":"This in-house investigation will examine the recycling rate for each section."}]'::jsonb),
    ('08d5e36f-7e81-4007-ac48-0ea47161da12'::uuid,ARRAY['(i) Noun 1 及び Noun 2']::text[],ARRAY['Use this construction to express A particle that connects two nouns or noun phrases.. A particle that connects two nouns or noun phrases.']::text[],ARRAY['【Related Expression: と; そして; 並びに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"使用した機種及びソフトウエアを表１に示す。","japanese_furigana":"使用した機種及びソフトウエアを表１に示す。","english":"The computer models and software we used are listed in Table 1."},{"japanese":"本奨学金への応募資格は、日本国籍を有すること、及び国内の四年制大学に在籍する学生であることである。","japanese_furigana":"本奨学金への応募資格は、日本国籍を有すること、及び国内の四年制大学に在籍する学生であることである。","english":"The qualifications for applying for this scholarship require (literally: are) that you be a Japanese citizen and a student at a four-year college in this country."}]'::jsonb),
    ('15e93379-4828-436a-a001-ea8e35795dd5'::uuid,ARRAY['(i) Noun 向け だ']::text[],ARRAY['Use this construction to express A suffix that adds the meaning of “aimed at”. A suffix that adds the meaning of “aimed at”']::text[],ARRAY['【Related Expression: よう; 向き】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"このギター曲集は初心者向けだ。","japanese_furigana":"このギター曲集は初心者向けだ。","english":"This collection of guitar pieces is for beginners."},{"japanese":"この秋はアジア向け（の）産業用ロボットの販売が好調だ。","japanese_furigana":"この秋はアジア向け（の）産業用ロボットの販売が好調だ。","english":"This autumn, sales of industrial robots for Asia have been good."}]'::jsonb),
    ('753a7272-37a0-4fc6-9945-4ee642133365'::uuid,ARRAY['(i) Last name 君']::text[],ARRAY['Use this construction to express A suffix attached to the first or last name of a male equal or to the first or last name of a person whose status or rank is lower than the speaker’s.. A suffix attached to the first or last name of a male equal or to the first or last name of a person whose status or rank is lower than the speaker’s.']::text[],ARRAY['【Related Expression: 様 (ちゃん; さん)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"もし、もし、一郎君いますか。","japanese_furigana":"もし、もし、一郎君いますか。","english":"Hello, is Ichiro in?"},{"japanese":"田口君が来年結婚するそうだ。","japanese_furigana":"田口君が来年結婚するそうだ。","english":"I heard that Mr. Taguchi will get married next year."}]'::jsonb),
    ('8aba2c88-6bf1-483f-b367-d54c36a9dd8e'::uuid,ARRAY['Canonical pattern: 〜屋']::text[],ARRAY['Use this construction to express A suffix attached to names of stores, inns and Japanese style restaurants or to persons engaged in certain occupations. A suffix attached to names of stores, inns and Japanese style restaurants or to persons engaged in certain occupations']::text[],ARRAY['The core sense is A suffix attached to names of stores, inns and Japanese style restaurants or to persons engaged in certain occupations; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"花屋 本屋 薬屋 肉屋 パチンコ屋 パン屋 魚屋 酒屋","japanese_furigana":"花屋 本屋 薬屋 肉屋 パチンコ屋 パン屋 魚屋 酒屋","english":"Florist bookstore drug store butcher pinball parlor bakery fishmonger liquor store"},{"japanese":"酒屋さんに電話してビールを三ダース持って来てもらった。","japanese_furigana":"酒屋さんに電話してビールを三ダース持って来てもらった。","english":"I called the man at the liquor store and had him bring me three dozen beers."}]'::jsonb),
    ('6c084ae3-5a27-4eae-a310-eaceae627671'::uuid,ARRAY['Vます うる / える']::text[],ARRAY['Use this construction to express An auxiliary verb that expresses possibility.. An auxiliary verb that expresses possibility.']::text[],ARRAY['【Related Expression: ことが出来る; られる】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"二十一世紀に日本語は国際語になり得ると思う。","japanese_furigana":"二十一世紀に日本語は国際語になり得ると思う。","english":"I think it''s possible for the Japanese language to become an international language in the 21st century."},{"japanese":"株の変動はいつでも起こり得る。","japanese_furigana":"株の変動はいつでも起こり得る。","english":"The fluctuation of stocks can happen any time."}]'::jsonb),
    ('6a8b9fcc-3bdb-46ba-aa6f-860685d5892b'::uuid,ARRAY['(i) 思うに 、 Sentence。']::text[],ARRAY['Use this construction to express A phrase indicating that the subsequent statement is the speaker’s/writer’s personal view.. A phrase indicating that the subsequent statement is the speaker’s/writer’s personal view.']::text[],ARRAY['【Related Expression: 考えるに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"(私が)思うに、文化は宗教の一種だ。","japanese_furigana":"(私が)思うに、文化は宗教の一種だ。","english":"In my view, culture is a kind of religion."},{"japanese":"医学界の体質を思うに、当然医者と製薬会社の癒着はあると思う。","japanese_furigana":"医学界の体質を思うに、当然医者と製薬会社の癒着はあると思う。","english":"Considering the nature of the medical world, I believe there is collusion between doctors and pharmaceutical companies."}]'::jsonb),
    ('d1ea0b90-59f9-45c7-8d81-afdeaabbd7ec'::uuid,ARRAY['(i) Nounの 恐れがある']::text[],ARRAY['Use this construction to express A phrase that means “it is feared (that)". A phrase that means “it is feared (that)"']::text[],ARRAY['【Related Expression: きけんせいがる; 心配がある; かのうせいがある; かもしれない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"台風の影響で、西日本は大雨の恐れがある。","japanese_furigana":"台風の影響で、西日本は大雨の恐れがある。","english":"Due to the typhoon (literally: the typhoon''s inﬂuence), there is a chance of heavy rain across Western Japan."},{"japanese":"この戦争は第二のベトナム戦争になる恐れがある。","japanese_furigana":"この戦争は第二のベトナム戦争になる恐れがある。","english":"This war could become a second Vietnam War. (literally: There is a risk that this war will become a second Vietnam War.)"}]'::jsonb),
    ('17a31026-fb78-4985-8aaf-13b9d93b9ca3'::uuid,ARRAY['(i) {Adjective い informal/Adjective な stem な/Vinformal} + (Noun の) +Vます 方をする']::text[],ARRAY['Use this construction to express A phrase to indicate a manner of doing something.. A phrase to indicate a manner of doing something.']::text[],ARRAY['【Related Expression: ように】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"林田先生は厳しい教え方をする。","japanese_furigana":"林田先生は厳しい教え方をする。","english":"Professor Hayashida teaches in a strict manner."},{"japanese":"昭は変わったものの見方をする。","japanese_furigana":"昭は変わったものの見方をする。","english":"Akira views things in a peculiar fashion."}]'::jsonb),
    ('42c59530-abda-4730-a05d-9529cf94875b'::uuid,ARRAY['Canonical pattern: 〜様']::text[],ARRAY['Use this construction to express A suffix (originally meaning ''appearance'') that indicates the speaker''s/writer''s politeness towards someone.. A suffix (originally meaning ''appearance'') that indicates the speaker''s/writer''s politeness towards someone.']::text[],ARRAY['【Related Expression: ちゃん; 君; さん】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"王様の耳は驢馬の耳だ。","japanese_furigana":"王様の耳は驢馬の耳だ。","english":"The King''s ears are donkey ears."},{"japanese":"神様を信じますか。","japanese_furigana":"神様を信じますか。","english":"Do you believe in God?"}]'::jsonb),
    ('76ba4885-5a99-4aea-8052-7ea0f8a95558'::uuid,ARRAY['滅多に ～ Vnegative ない']::text[],ARRAY['Use this construction to express A structure that indicates extremely low frequency.. A structure that indicates extremely low frequency.']::text[],ARRAY['【Related Expression: たまには; あまり~ない; ほとんど~ない; たましか~ない; 時たましか~ない; 全然~ない; 全く~ない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この辺りでは地震は滅多に起きない。","japanese_furigana":"この辺りでは地震は滅多に起きない。","english":"Earthquakes seldom occur in this area."},{"japanese":"日本の父親は忙しいので、週末でも滅多にうちにいない。","japanese_furigana":"日本の父親は忙しいので、週末でも滅多にうちにいない。","english":"Japanese fathers are so busy that even on weekends they are seldom at home."}]'::jsonb),
    ('b6c881fe-0ca5-4afc-a829-f5a5c5d05621'::uuid,ARRAY['Number+Counter 目']::text[],ARRAY['Use this construction to express A suffix which represents an ordinal number.. A suffix which represents an ordinal number.']::text[],ARRAY['The core sense is A suffix which represents an ordinal number.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私の車は右から二台目です。","japanese_furigana":"私の車は右から二台目です。","english":"My car is the second one from the right."},{"japanese":"それは上から三つ目の引き出しに入っています。","japanese_furigana":"それは上から三つ目の引き出しに入っています。","english":"It is in the third drawer from the top."}]'::jsonb),
    ('30939837-8c33-46b7-b5aa-93033b51a227'::uuid,ARRAY['Canonical pattern: 〜確かに〜が']::text[],ARRAY['Use this construction to express A structure which expresses the idea "indeed ~ but".. A structure which expresses the idea "indeed ~ but".']::text[],ARRAY['【Related Expression: ことは~が】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この車は確かに魅力的だが、値段が高すぎる。","japanese_furigana":"この車は確かに魅力的だが、値段が高すぎる。","english":"This car is certainly attractive, but the price is too high."},{"japanese":"そのパーティーのことは確かに聞いたが、いつだったか思い出せない。","japanese_furigana":"そのパーティーのことは確かに聞いたが、いつだったか思い出せない。","english":"I certainly heard about the party, but I don''t remember when it is going to be."}]'::jsonb),
    ('46ed856c-c65b-45a3-9609-d564cd2fac35'::uuid,ARRAY['(i) 見るからに Adjective(い/な) stemそうだ']::text[],ARRAY['Use this construction to express A phrase indicating that something can be (obviously) recognized through visual cues.. A phrase indicating that something can be (obviously) recognized through visual cues.']::text[],ARRAY['【Related Expression: 明らかに; いかにも】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"太陽の光をたっぷり浴びたみかんは、見るからにおいしそうだ。","japanese_furigana":"太陽の光をたっぷり浴びたみかんは、見るからにおいしそうだ。","english":"The sun-bathed mandarin oranges look really delicious."},{"japanese":"彼女が身につけているものは見るからに高級品だった。","japanese_furigana":"彼女が身につけているものは見るからに高級品だった。","english":"What she wears is obviously of high quality."}]'::jsonb),
    ('c3d6e78e-d688-4501-9f6c-7fd84d353fda'::uuid,ARRAY['(i) {V/Adjectiveい} informal+Nominalは 言うまでもない 。']::text[],ARRAY['Use this construction to express A phrase indicating that what the speaker/writer expresses is generally known but that he/she presents it as a reminder.. A phrase indicating that what the speaker/writer expresses is generally known but that he/she presents it as a reminder.']::text[],ARRAY['The core sense is A phrase indicating that what the speaker/writer expresses is generally known but that he/she presents it as a reminder.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"寿司が日本の代表的な料理であることは言うまでもない。","japanese_furigana":"寿司が日本の代表的な料理であることは言うまでもない。","english":"It goes without saying that sushi is representative of Japanese cuisine."},{"japanese":"言うまでもなく、日本の社会は世界一の高齢化社会になっている。","japanese_furigana":"言うまでもなく、日本の社会は世界一の高齢化社会になっている。","english":"That Japan has become the most rapidly aging society in the world goes without saying."}]'::jsonb),
    ('01589d45-9db0-43c3-a9c3-e8d804376d0b'::uuid,ARRAY['(i) 言ってみれば Sentence。 Where Sentence is a simile or a metaphor']::text[],ARRAY['Use this construction to express A phrase signalling a comparison (including the use of simile and metaphor), a deﬁnition, or an explanation.. A phrase signalling a comparison (including the use of simile and metaphor), a deﬁnition, or an explanation.']::text[],ARRAY['【Related Expression: 言わば; 例えて言えば; (例えて)言うならば】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"言ってみれば、人生は航海（のようなもの）だ。","japanese_furigana":"言ってみれば、人生は航海（のようなもの）だ。","english":"Figuratively speaking, life is (like) a voyage."},{"japanese":"彼女の家は、言ってみれば、お城のように作られている。","japanese_furigana":"彼女の家は、言ってみれば、お城のように作られている。","english":"You could say her house is built like a castle."}]'::jsonb),
    ('f4b1b452-302f-4a4e-921c-d015abbcf204'::uuid,ARRAY['Noun 1 と言わず Noun 2 と言わず']::text[],ARRAY['Use this construction to express A structure indicating that something is the case not only for A and B but also for many other places, things, etc., of X, to which A and B belong. A structure indicating that something is the case not only for A and B but also for many other places, things, etc., of X, to which A and B belong']::text[],ARRAY['【Related Expression: だろうが/と~だろうが/と; であろうが/と~であろうが/と; であれ~であれ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"友達の引っ越しを手伝ったら、翌日肩と言わず腰と言わず体のあちこちが痛んだ。","japanese_furigana":"友達の引っ越しを手伝ったら、翌日肩と言わず腰と言わず体のあちこちが痛んだ。","english":"I helped my friend move. Then, the next day my shoulders, my back and every other part of my body ached."},{"japanese":"武史の部屋は、壁と言わず天井と言わず、いたるところにサッカーの写真が貼ってあった。","japanese_furigana":"武史の部屋は、壁と言わず天井と言わず、いたるところにサッカーの写真が貼ってあった。","english":"In Takeshi''s room, pictures of soccer were posted on the walls, the ceiling and everywhere else."}]'::jsonb),
    ('6239bc7f-2bf0-4fea-8829-14e23e448000'::uuid,ARRAY['(i) Noun (time) 限り']::text[],ARRAY['Use this construction to express A suffix which expresses the idea of "(last) only until" or "limited".. A suffix which expresses the idea of "(last) only until" or "limited".']::text[],ARRAY['The core sense is A suffix which expresses the idea of "(last) only until" or "limited".; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"今度限りで彼のパーティーには行かないつもりだ。","japanese_furigana":"今度限りで彼のパーティーには行かないつもりだ。","english":"This is the last time I am going to any of his parties."},{"japanese":"切符は一人二枚限りです。","japanese_furigana":"切符は一人二枚限りです。","english":"Tickets are limited to two per person."}]'::jsonb),
    ('bea4e98f-1564-4f4d-9a09-0cc8227e0bd1'::uuid,ARRAY['(i) Vinformal 限り']::text[],ARRAY['Use this construction to express A conjunction which expresses the idea "as long as (a certain condition is met)" or "as long as (= to the extent)".. A conjunction which expresses the idea "as long as (a certain condition is met)" or "as long as (= to the extent)".']::text[],ARRAY['【Related Expression: あいだは; うちは】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私がここにいる限り心配は無用です。","japanese_furigana":"私がここにいる限り心配は無用です。","english":"As long as I am here, you don''t have to worry."},{"japanese":"田中さんが来ない限りこの会議は始められない。","japanese_furigana":"田中さんが来ない限りこの会議は始められない。","english":"As long as Mr. Tanaka is not here (literally: does not come), we cannot begin this meeting."}]'::jsonb)
), invalid as (
  select grammar_id from enrichment where not public.repository_reference_examples_valid(examples_value)
)
select case when count(*)=0 then true else false end as payloads_valid from invalid;

with enrichment(grammar_id,formation_value,usage_value,nuance_value,examples_value) as (
  values
    ('b06e5382-f940-4a0f-bfaf-f5adca154665'::uuid,ARRAY['(i) {V/Adjective い} informal の']::text[],ARRAY['Use this construction to express A sentence-final particle used by a female or a child to indicate an explanation or emotive emphasis.. A sentence-final particle used by a female or a child to indicate an explanation or emotive emphasis.']::text[],ARRAY['【Related Expression: のだ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"A:どうして泣いているの？ B:お母さんがいないの。","japanese_furigana":"A:どうして泣いているの？ B:お母さんがいないの。","english":"A: How come you are crying? B: ''Cause mommy''s gone."},{"japanese":"あの人はとても優しいの。","japanese_furigana":"あの人はとても優しいの。","english":"He is so gentle, you know."}]'::jsonb),
    ('a3291689-be57-4f8c-9fc1-e0055762518a'::uuid,ARRAY['(i) Noun の Noun 田中さん の 家 Mr. Tanaka’s house']::text[],ARRAY['Use this construction to express A particle which, with a preceding noun phrase, forms a phrase to modify a following noun phrase.. A particle which, with a preceding noun phrase, forms a phrase to modify a following noun phrase.']::text[],ARRAY['【Related Expression: の2】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"これは先生の本だ・です。","japanese_furigana":"これは先生の本だ・です。","english":"This is my teacher''s book."},{"japanese":"これは友達からの手紙だ・です。","japanese_furigana":"これは友達からの手紙だ・です。","english":"This is a letter from my friend."}]'::jsonb),
    ('c4091543-1ddd-481b-9f73-b5af13a2a43b'::uuid,ARRAY['(i) {V/Adjectiveい}informal のなんのって']::text[],ARRAY['Use this construction to express A phrase to emphasize that something/someone is/was in an extreme state or that someone does/did something to a great extent. A phrase to emphasize that something/someone is/was in an extreme state or that someone does/did something to a great extent']::text[],ARRAY['【Related Expression: の~ないのって; なんてもんじゃない; などと言うものではない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"甘いのなんのって私は一口食べて全部残してしまいました。","japanese_furigana":"甘いのなんのって私は一口食べて全部残してしまいました。","english":"It was so sweet that I ate one bite and left the rest."},{"japanese":"飲んだのなんのって彼らは5本の酒を全部空けてしまった。","japanese_furigana":"飲んだのなんのって彼らは5本の酒を全部空けてしまった。","english":"They drank so much; they completely emptied ﬁve bottles of sake."}]'::jsonb),
    ('e79cbed9-bd3b-4e4e-a695-237ad0da8e4c'::uuid,ARRAY['Vinformal nonpast のに']::text[],ARRAY['Use this construction to express In the process or for the purpose of doing something expressed in the の nominalised clause.. In the process or for the purpose of doing something expressed in the の nominalised clause.']::text[],ARRAY['【Related Expression: に5; 為(に)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は日本語の新聞を読むのに辞書を使う・使います。","japanese_furigana":"私は日本語の新聞を読むのに辞書を使う・使います。","english":"I used a dictionary to read Japanese newspapers."},{"japanese":"すき焼きを作るのには何が要りますか。","japanese_furigana":"すき焼きを作るのには何が要りますか。","english":"What do you need to make sukiyaki?"}]'::jsonb),
    ('6026f814-0214-4361-ae12-2754bfd9894f'::uuid,ARRAY['(i) {V/Adjective い} informal のは～だ']::text[],ARRAY['Use this construction to express A structure that indicates new, important information by placing it between [x] and the copula [x] ([x] is an indefinite pronoun ([x]2) that replaces ‘time’,’person’, ‘thing’, ‘place’ or ‘reason’.). A structure that indicates new, important information by placing it between [x] and the copula [x] ([x] is an indefinite pronoun ([x]2) that replaces ‘time’,’person’, ‘thing’, ‘place’ or ‘reason’.)']::text[],ARRAY['【Related Expression: の3】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私が中国に行ったのは三年前だ・です。","japanese_furigana":"私が中国に行ったのは三年前だ・です。","english":"It was three years ago that I went to China. / The time when I went to China was three years ago."},{"japanese":"このクラスで一番頭がいいのは吉田さんだ・です。","japanese_furigana":"このクラスで一番頭がいいのは吉田さんだ・です。","english":"The brightest one in this class is Mr. Yoshida."}]'::jsonb),
    ('79045f4d-05ad-41ff-888f-61f47ccb6879'::uuid,ARRAY['Sinformal のは Noun のことだ (the same formation as のだ)']::text[],ARRAY['Use this construction to express A structure which focuses on a time when something takes place.. A structure which focuses on a time when something takes place.']::text[],ARRAY['The core sense is A structure which focuses on a time when something takes place.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"吉田さんと最後に会ったのは１９８５年の五月のことだ。","japanese_furigana":"吉田さんと最後に会ったのは１９８５年の五月のことだ。","english":"It was in May 1985 that I last met Mr. Yamada."},{"japanese":"日本語の面白さが分かり始めたのはごく最近のことだ。","japanese_furigana":"日本語の面白さが分かり始めたのはごく最近のことだ。","english":"It was only recently that I began to understand how interesting Japanese is."}]'::jsonb),
    ('de6f02c4-9dde-45d5-9a42-b2d0df738940'::uuid,ARRAY['(i) Noun のみ (Particle)']::text[],ARRAY['Use this construction to express A particle which expresses a limit imposed upon an action, event, or a state.. A particle which expresses a limit imposed upon an action, event, or a state.']::text[],ARRAY['【Related Expression: だけ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"要点のみ（を）話して下さい。","japanese_furigana":"要点のみ（を）話して下さい。","english":"Please tell me just the main point."},{"japanese":"これは吉田先生にのみ話してあります。","japanese_furigana":"これは吉田先生にのみ話してあります。","english":"I have told this only to Professor Yoshida."}]'::jsonb),
    ('a60e41d0-91d4-4812-8494-372fe869c56f'::uuid,ARRAY['(i) Noun (Particle) のみならず']::text[],ARRAY['Use this construction to express A phrase that is used in formal writing to mean “not only”.. A phrase that is used in formal writing to mean “not only”.']::text[],ARRAY['【Related Expression: だけで(は)なく; に限らず; にとどまらず; はおろか】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"我が社は日本国内のみならず、アメリカやヨーロッパなどでもビジネス活動を行っております。","japanese_furigana":"我が社は日本国内のみならず、アメリカやヨーロッパなどでもビジネス活動を行っております。","english":"Our company does business not only in Japan but also in America, Europe, and elsewhere."},{"japanese":"これからの企業は単に利益を追求するのみならず、環境に配慮した生産活動を行わなければならない。","japanese_furigana":"これからの企業は単に利益を追求するのみならず、環境に配慮した生産活動を行わなければならない。","english":"Today''s companies should not just pursue profits; they should also consider environmental protection issues in their production activities. (literally: they must perform production activities that take the environment into consideration as well.)"}]'::jsonb),
    ('c9d75736-0ac9-4670-8c3e-3a4a3c591244'::uuid,ARRAY['Noun の無さ']::text[],ARRAY['Use this construction to express A phrase that indicates a state where something is lacking.. A phrase that indicates a state where something is lacking.']::text[],ARRAY['The core sense is A phrase that indicates a state where something is lacking.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私は彼の常識の無さにあきれている。","japanese_furigana":"私は彼の常識の無さにあきれている。","english":"I am appalled by his lack of common sense."},{"japanese":"跳びたいと思っても跳べない。体力、筋力の無さを痛感しました。","japanese_furigana":"跳びたいと思っても跳べない。体力、筋力の無さを痛感しました。","english":"I wanted to jump, but I couldn''t. I became painfully aware of my lack of physical and muscular strength."}]'::jsonb),
    ('7ea355c9-8839-4803-ab19-9c5165318f8e'::uuid,ARRAY['Noun の関係で']::text[],ARRAY['Use this construction to express A phrase indicating that something takes place or does not take place because of something.. A phrase indicating that something takes place or does not take place because of something.']::text[],ARRAY['【Related Expression: の為(に)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ホールさんは今仕事の関係で東京に行っています。","japanese_furigana":"ホールさんは今仕事の関係で東京に行っています。","english":"Mr. Hall has gone to Tokyo on a business-related matter."},{"japanese":"鈴木は単位の関係で今年は卒業出来ないそうだ。","japanese_furigana":"鈴木は単位の関係で今年は卒業出来ないそうだ。","english":"I heard that Suzuki cannot graduate this year because of insufficient credits / units."}]'::jsonb),
    ('afef6379-c3f9-4295-ba8f-083830571b34'::uuid,ARRAY['(i) Vます は {する(が)/しない}']::text[],ARRAY['Use this construction to express A particle which emphatically affirms or negates the proposition represented by the preceding verbal and other related elements.. A particle which emphatically affirms or negates the proposition represented by the preceding verbal and other related elements.']::text[],ARRAY['【Related Expression: ことは】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"行きはしますが、何も手伝えませんよ。","japanese_furigana":"行きはしますが、何も手伝えませんよ。","english":"I am going (there) but I cannot help you, all right?"},{"japanese":"疲れてはいるが、まだ休みたくない。","japanese_furigana":"疲れてはいるが、まだ休みたくない。","english":"I am tired but I don''t want to take a break yet."}]'::jsonb),
    ('39cf0cb6-145f-455a-8995-6f0a9ce59cdd'::uuid,ARRAY['Noun はあれ']::text[],ARRAY['Use this construction to express A phrase expressing the idea “even though there is something”. A phrase expressing the idea “even though there is something”']::text[],ARRAY['【Related Expression: はあっても】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"インターフェースに若干の違いはあれ、この二つのプログラムは機能的には全く変わらない。","japanese_furigana":"インターフェースに若干の違いはあれ、この二つのプログラムは機能的には全く変わらない。","english":"Although their interfaces are slightly different, these two programs are just the same in terms of their functions."},{"japanese":"歴史の違いはあれ、米国には１２０万を越す非営利団体(NPO)が存在します。","japanese_furigana":"歴史の違いはあれ、米国には１２０万を越す非営利団体(NPO)が存在します。","english":"Although their histories are different (literally: there are differences in their histories), there are more than 1,200,000 non-profit organizations in America."}]'::jsonb),
    ('d9ff78b0-1f62-4559-ac3d-f5e96cf286a8'::uuid,ARRAY['(i) Noun はいいとしても']::text[],ARRAY['Use this construction to express A phrase that conveys the meaning “even if I/we accept something, something else is not acceptable”.. A phrase that conveys the meaning “even if I/we accept something, something else is not acceptable”.']::text[],ARRAY['【Related Expression: は仕方がないとしても】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"友達を助けようという動機はいいとしてもやり方が間違っている。","japanese_furigana":"友達を助けようという動機はいいとしてもやり方が間違っている。","english":"Your motivation for helping your friend is all right, but your way (of doing it) is wrong."},{"japanese":"私はいいとしても他の人がこの部屋では満足しないだろう。","japanese_furigana":"私はいいとしても他の人がこの部屋では満足しないだろう。","english":"Even if I accept it, other people wouldn''t be satisﬁed with this room."}]'::jsonb),
    ('8ffd82a7-689b-4c62-a27d-26077c5557f6'::uuid,ARRAY['Vて はいけない']::text[],ARRAY['Use this construction to express A phrase which indicates prohibition.. A phrase which indicates prohibition.']::text[],ARRAY['【Related Expression: はならない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この部屋に入ってはいけない・いけません。","japanese_furigana":"この部屋に入ってはいけない・いけません。","english":"You must not enter this room."},{"japanese":"教室でものを食べてはいけません。","japanese_furigana":"教室でものを食べてはいけません。","english":"You must not eat (food) in the classroom."}]'::jsonb),
    ('59fc5d1f-aaef-4eff-ac77-281a68e8c245'::uuid,ARRAY['Noun 1 はおろか Noun 2 {も/でも/さえ/すら/まで}']::text[],ARRAY['Use this construction to express A phrase that is used when something is not only true with one thing or person, but also with another thing or person that is less expected or understandable.. A phrase that is used when something is not only true with one thing or person, but also with another thing or person that is less expected or understandable.']::text[],ARRAY['【Related Expression: は言うまでもなく; は言うに及ばず; はもちろん; だけでなく; のみならず】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"インターネットはおろか、パソコンも触ってことがないのだが、講習会についていけるだろうか。","japanese_furigana":"インターネットはおろか、パソコンも触ってことがないのだが、講習会についていけるだろうか。","english":"Never having touched a computer, let alone used the Internet, I wonder if I will be able to keep up in the workshop."},{"japanese":"最近は大学生はおろか、中学生でもかなりの者が海外旅行を経験している。","japanese_furigana":"最近は大学生はおろか、中学生でもかなりの者が海外旅行を経験している。","english":"Never mind college students, these days even junior and senior high school students often have experienced traveling abroad."}]'::jsonb),
    ('99b8d05d-2cf6-434f-a915-e37d03766d04'::uuid,ARRAY['(i) Vinformal nonpast ばかり']::text[],ARRAY['Use this construction to express A particle which indicates that something is the only thing or state which exists, or the action someone will take, takes, is taking or took.. A particle which indicates that something is the only thing or state which exists, or the action someone will take, takes, is taking or took.']::text[],ARRAY['【Related Expression: ほど(くらい); しか (だけ); とろこだ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"デザートは食べるばかりになっている・います。","japanese_furigana":"デザートは食べるばかりになっている・います。","english":"The only thing left to do with the dessert is to eat it./The dessert is ready to eat."},{"japanese":"友子は遊んでばかりいる・います。","japanese_furigana":"友子は遊んでばかりいる・います。","english":"The only thing Tomoko is doing is playing./Tomoko is doing nothing but playing."}]'::jsonb),
    ('e78894fa-adc2-4b81-bb70-d817118b1aa8'::uuid,ARRAY['(i) {V/ Adjective い} informal ばかりか']::text[],ARRAY['Use this construction to express A compound particle/conjunction which is used to connect two nouns or two sentences, the first of which is something normally expected and the second of which is something normally unexpected.. A compound particle/conjunction which is used to connect two nouns or two sentences, the first of which is something normally expected and the second of which is something normally unexpected.']::text[],ARRAY['【Related Expression: ばかりで(は)なく~も; だけで(は)なく~も; どころか】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本では子供ばかりか大人さえ漫画を読んでいる。","japanese_furigana":"日本では子供ばかりか大人さえ漫画を読んでいる。","english":"In Japan not only children but even adults are reading comic books."},{"japanese":"あの人は絵を見て楽しむばかりか、自分でも絵を描く。","japanese_furigana":"あの人は絵を見て楽しむばかりか、自分でも絵を描く。","english":"He not only enjoys looking at pictures; he also draws them."}]'::jsonb),
    ('66d550e6-b174-4274-b4ba-8953d9cc7a06'::uuid,ARRAY['(i) NP は別として']::text[],ARRAY['Use this construction to express A phrase used to present an exception or an issue the speaker/writer does not intend to cover as part of a larger statement.. A phrase used to present an exception or an issue the speaker/writer does not intend to cover as part of a larger statement.']::text[],ARRAY['【Related Expression: を覗いて; 以外は; はさておき】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"特殊な場合は別として、手書きのレポートを書くことは少なくなった。","japanese_furigana":"特殊な場合は別として、手書きのレポートを書くことは少なくなった。","english":"Except for special cases, there are only a few occasions now in which we write hand-written reports."},{"japanese":"実施できるか(どうか)は別として、まず可能な解決策をすべてリストアップしてみよう。","japanese_furigana":"実施できるか(どうか)は別として、まず可能な解決策をすべてリストアップしてみよう。","english":"Putting aside the question of whether or not each one is feasible for us to carry out, let''s list all possible solutions ﬁrst."}]'::jsonb),
    ('db6b93c1-a6e2-49c1-a673-0ac807ac951d'::uuid,ARRAY['Canonical pattern: 〜へ']::text[],ARRAY['Use this construction to express A particle that indicates the direction toward which some directional movement or action proceeds.. A particle that indicates the direction toward which some directional movement or action proceeds.']::text[],ARRAY['【Related Expression: まで; に4; に7】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は先週京都へ旅行に行った・行きました。","japanese_furigana":"私は先週京都へ旅行に行った・行きました。","english":"I went on a trip to Kyoto last week."},{"japanese":"私は札幌のうちへ飛行機で帰った。","japanese_furigana":"私は札幌のうちへ飛行機で帰った。","english":"I went back home to Sapporo by plane."}]'::jsonb),
    ('241843b7-56ce-4c34-a0ba-2fd86adf9812'::uuid,ARRAY['(i) Vinformal nonpast べからず Exception: する→{す/する}べからず']::text[],ARRAY['Use this construction to express An auxiliary verb that indicates a strong prohibition.. An auxiliary verb that indicates a strong prohibition.']::text[],ARRAY['【Related Expression: Verb informal nonpast な; を禁ず(る); 禁止; てはいけません; ないで下さい; ないようにして下さい】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"芝生に入るべからず。","japanese_furigana":"芝生に入るべからず。","english":"Keep off the lawn. (literally: Don''t enter the lawn.)"},{"japanese":"原子力はエネルギー源として欠くべからざるものとなっている。","japanese_furigana":"原子力はエネルギー源として欠くべからざるものとなっている。","english":"Atomic energy has become indispensable as a source of energy."}]'::jsonb),
    ('0980c029-3de8-4410-89b2-7c2b57c474b0'::uuid,ARRAY['(i) Vinformal nonpast べきだ']::text[],ARRAY['Use this construction to express An auxiliary which expresses the speaker''s judgment that someone/something should do something or should be in some state.. An auxiliary which expresses the speaker''s judgment that someone/something should do something or should be in some state.']::text[],ARRAY['【Related Expression: はず; 方がいい; ものだ; なければならない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この論文は書き直すべきだ。","japanese_furigana":"この論文は書き直すべきだ。","english":"This thesis should be rewritten."},{"japanese":"そんなことを人に言うべき{では/じゃ}ありません。","japanese_furigana":"そんなことを人に言うべき{では/じゃ}ありません。","english":"You shouldn''t say that kind of thing to people."}]'::jsonb),
    ('6f72ab19-502f-4849-9150-af3cde2dec38'::uuid,ARRAY['V1informal nonpast べくして V2 (where V1=V2) Exception: する→{す/する}べくして']::text[],ARRAY['Use this construction to express A phrase used when something occurs/occured exactly as expected. A phrase used when something occurs/occured exactly as expected']::text[],ARRAY['【Related Expression: やはり/やっぱり】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"第二次世界大戦は起こるべくして起こった。","japanese_furigana":"第二次世界大戦は起こるべくして起こった。","english":"World War II occurred, exactly as expected."},{"japanese":"彼は大統領になるべくしてなった。","japanese_furigana":"彼は大統領になるべくしてなった。","english":"He became president, exactly as expected."}]'::jsonb),
    ('cf6b495e-1ced-4ca3-bd81-c6bc3ea0ce75'::uuid,ARRAY['Vinformal nonpast べくもない する→{す/する}べくもない']::text[],ARRAY['Use this construction to express A phrase meaning “it is impossible to do something”. A phrase meaning “it is impossible to do something”']::text[],ARRAY['【Related Expression: Verb potential わけがない; Verb potential はずがない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私が一億円の家を買うなど、望むべくもない。","japanese_furigana":"私が一億円の家を買うなど、望むべくもない。","english":"It is impossible for me to hope to buy a hundred million yen house."},{"japanese":"十年前に別れた女性の居どころなど知るべくもない。","japanese_furigana":"十年前に別れた女性の居どころなど知るべくもない。","english":"There is no way for me to know the whereabouts of the woman I split up with 10 years ago."}]'::jsonb),
    ('faf76bbf-01ee-470d-b2ae-a377466289ef'::uuid,ARRAY['(i) Vinformal nonpast まい']::text[],ARRAY['Use this construction to express An auxiliary which expresses the speaker''s negative volition or conjecture.. An auxiliary which expresses the speaker''s negative volition or conjecture.']::text[],ARRAY['The core sense is An auxiliary which expresses the speaker''s negative volition or conjecture.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"もう橋本には何も頼むまい。","japanese_furigana":"もう橋本には何も頼むまい。","english":"I will not ask any more favours of Hashimoto."},{"japanese":"これは恐らく誰も気が付くまい。","japanese_furigana":"これは恐らく誰も気が付くまい。","english":"Probably no one will notice this."}]'::jsonb),
    ('7124e7b5-6178-4628-ad4f-0d727378ed97'::uuid,ARRAY['Canonical pattern: 〜ましだ']::text[],ARRAY['Use this construction to express A phrase indicating that although someone/something (or some situation) is not satisfactory it is better than someone/something else.. A phrase indicating that although someone/something (or some situation) is not satisfactory it is better than someone/something else.']::text[],ARRAY['【Related Expression: いい】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"こんな給料をもらう（くらい）なら辞めた方がましだ。","japanese_furigana":"こんな給料をもらう（くらい）なら辞めた方がましだ。","english":"If this is the salary, it would be better to quit."},{"japanese":"今度の日本語の先生は前の先生よりずっとましだ。","japanese_furigana":"今度の日本語の先生は前の先生よりずっとましだ。","english":"This new Japanese teacher is much better than the former teacher."}]'::jsonb),
    ('6659e3de-f18e-42c4-abef-16f390948078'::uuid,ARRAY['Vinformal まで(のこと)だ']::text[],ARRAY['Use this construction to express A phrase indicating someone’s decision to cope with a negative situation, or a simple, straight forward reason for his/her action.. A phrase indicating someone’s decision to cope with a negative situation, or a simple, straight forward reason for his/her action.']::text[],ARRAY['【Related Expression: だから(のこと)だ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"もしTOEFLの点が悪かったらもう一度受けるまで（のこと）だ。","japanese_furigana":"もしTOEFLの点が悪かったらもう一度受けるまで（のこと）だ。","english":"If my TOEFL score isn''t good, then I''ll just take the test again."},{"japanese":"日本語は面白そうだったので、取ったまで（このと）だ。","japanese_furigana":"日本語は面白そうだったので、取ったまで（このと）だ。","english":"I took Japanese language only because it looked interesting (not for any other reason)."}]'::jsonb),
    ('d562820b-72d8-413a-b4b5-80fd0dc5e4de'::uuid,ARRAY['Number+Counter も Vconditional']::text[],ARRAY['Use this construction to express A structure which expresses the idea that a certain amount of something is sufficient to do something.. A structure which expresses the idea that a certain amount of something is sufficient to do something.']::text[],ARRAY['The core sense is A structure which expresses the idea that a certain amount of something is sufficient to do something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"この美術館は三時間もあれば全部見られる。","japanese_furigana":"この美術館は三時間もあれば全部見られる。","english":"Three hours are enough to see everything in this art museum. (literally: If you have as many as three hours, you can see everything in this art museum.)"},{"japanese":"二万円も持って行けば足りるでしょう。","japanese_furigana":"二万円も持って行けば足りるでしょう。","english":"20,000 yen will probably be enough. (literally: If you take as much as 20,000 yen with you, it will probably be sufficient.)"}]'::jsonb),
    ('48584d64-a377-44f2-87ee-110cee809d41'::uuid,ARRAY['(i) V1ます も すれ ば V2ます も する']::text[],ARRAY['Use this construction to express A structure used to present typical examples of actions, events, situations, people, or things among a number of possibilities.. A structure used to present typical examples of actions, events, situations, people, or things among a number of possibilities.']::text[],ARRAY['【Related Expression: も[Verb]し~も[Verb]; たり~たりする】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"父は感情的な人ではないが、時に怒りもすれば泣きもする。","japanese_furigana":"父は感情的な人ではないが、時に怒りもすれば泣きもする。","english":"My father is not an emotional person, but there are times when he gets angry and times when he cries."},{"japanese":"私だってロックも聞けばダンスもする。","japanese_furigana":"私だってロックも聞けばダンスもする。","english":"Even I sometimes (do things like) listen to rock music and dance."}]'::jsonb),
    ('113538cd-81ba-4f7b-a100-dd8c53c572ae'::uuid,ARRAY['NP もさることながら']::text[],ARRAY['Use this construction to express A phrase used to mention something important and then introduce something more signiﬁcant.. A phrase used to mention something important and then introduce something more signiﬁcant.']::text[],ARRAY['The core sense is A phrase used to mention something important and then introduce something more signiﬁcant.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"この図書館は蔵書の多さもさることながらサービスが実にすばらしい。","japanese_furigana":"この図書館は蔵書の多さもさることながらサービスが実にすばらしい。","english":"This library''s large collection of books is one thing (literally: is so, too), but the services they provide are really something else (literally: really wonderful)."},{"japanese":"指圧やマッサージといった「タッチセラピー」が注目されている。身体への直接的な効果もさることながら、安らぎ感や癒しといった心理的な効果も大きいようだ。","japanese_furigana":"指圧やマッサージといった「タッチセラピー」が注目されている。身体への直接的な効果もさることながら、安らぎ感や癒しといった心理的な効果も大きいようだ。","english":"“Touch therapies,” such as shiatsu and massage, are drawing people''s attention. While they have a direct effect on the body (literally: Their direct effect is so, too), apparently their psychological effect, including feelings of relaxation and healing, is also great."}]'::jsonb),
    ('4a61e133-174c-486f-8fd9-567ccee38e5a'::uuid,ARRAY['(i) {V/Adjectiveい}informal nonpast ものか']::text[],ARRAY['Use this construction to express A rhetorical question marker that expresses a strong negative intention or disagreement.. A rhetorical question marker that expresses a strong negative intention or disagreement.']::text[],ARRAY['The core sense is A rhetorical question marker that expresses a strong negative intention or disagreement.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"あんなやつとは二度と会うものか。","japanese_furigana":"あんなやつとは二度と会うものか。","english":"I will never see that sort of guy again."},{"japanese":"A:彼は5年後には自分でコンピュータの会社をつくるって言っているよ。 B:そんなこと彼にできるもんか。","japanese_furigana":"A:彼は5年後には自分でコンピュータの会社をつくるって言っているよ。 B:そんなこと彼にできるもんか。","english":"A: He says he will establish a computer company by himself in five years. B: I bet he can''t. (literally: Can he do it?)"}]'::jsonb),
    ('c8cfd628-3f4d-4c4d-8800-9c5513707bbd'::uuid,ARRAY['(i) Vpotential negativeない もの (だろう) か']::text[],ARRAY['Use this construction to express A phrase indicating that the speaker wants to do something or is wondering what one he/she should choose.. A phrase indicating that the speaker wants to do something or is wondering what one he/she should choose.']::text[],ARRAY['【Related Expression: たらいいのに; たらいいのだが; たらいいか; べきか】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"もう少し広い家に住めないもの（だろう）か。","japanese_furigana":"もう少し広い家に住めないもの（だろう）か。","english":"(i) I wish to live in a house that is a bit more spacious. (ii) I wonder if I can live in a slightly more spacious house."},{"japanese":"修士論文の題目をどのように決めたものか（と）迷っています。","japanese_furigana":"修士論文の題目をどのように決めたものか（と）迷っています。","english":"I am at a loss as to how I should choose my MA thesis topic."}]'::jsonb),
    ('bbbb1c30-bb58-44ae-94c0-c21e4afa378c'::uuid,ARRAY['(i) X やら Y やら']::text[],ARRAY['Use this construction to express A structure to present things, events, actions, etc., as examples, reasons or possibilities.. A structure to present things, events, actions, etc., as examples, reasons or possibilities.']::text[],ARRAY['【Related Expression: や~や; とか~とか; たり~たり; か~か; わ~わ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は会議やら講習会やらでこのところ出張が続いている。","japanese_furigana":"私は会議やら講習会やらでこのところ出張が続いている。","english":"I have been traveling for business a lot these days to conferences, workshops, etc."},{"japanese":"みんなに自分の写真をほめられて嬉しいやら恥ずかしいやら(で)変な気持ちでした。","japanese_furigana":"みんなに自分の写真をほめられて嬉しいやら恥ずかしいやら(で)変な気持ちでした。","english":"When people praised the picture of me I felt strange, both happy and shy."}]'::jsonb),
    ('3643d29a-236f-4d63-a155-7db3978e2f80'::uuid,ARRAY['(i) Vvolitional V: non-controllable verb']::text[],ARRAY['Use this construction to express An auxiliary verb that expresses the writer''s conjecture about some potentiality or his certainty about a given state of affairs.. An auxiliary verb that expresses the writer''s conjecture about some potentiality or his certainty about a given state of affairs.']::text[],ARRAY['【Related Expression: だろう; でしょう】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この程度の文章なら日本語の一年生でも読めよう。","japanese_furigana":"この程度の文章なら日本語の一年生でも読めよう。","english":"Even the first year students of Japanese (probably) can read a passage of this level."},{"japanese":"こんな寒い日にオーバーも着ないで歩き回れば、風邪も引こう。","japanese_furigana":"こんな寒い日にオーバーも着ないで歩き回れば、風邪も引こう。","english":"If you walk around without wearing an overcoat on such a cold day, it is a matter of course that you will catch a cold."}]'::jsonb),
    ('ae9fbffa-09be-4bdd-b4e5-8f7e2ae12d55'::uuid,ARRAY['Vます よう']::text[],ARRAY['Use this construction to express A noun forming suffix which means a way (of doing something).. A noun forming suffix which means a way (of doing something).']::text[],ARRAY['【Related Expression: 方】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この作文は直しようがない。","japanese_furigana":"この作文は直しようがない。","english":"There is no way to correct this composition."},{"japanese":"この成績じゃ・では救いようがない。","japanese_furigana":"この成績じゃ・では救いようがない。","english":"There is no way to save (him) with this grade."}]'::jsonb),
    ('71cc823b-e002-444f-8de8-62dd5ba6357f'::uuid,ARRAY['(i) Vvolitional { と / が }']::text[],ARRAY['Use this construction to express A conjunctive phrase that expresses the idea of concession.. A conjunctive phrase that expresses the idea of concession.']::text[],ARRAY['【Related Expression: ても; ようとも】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"人が何と言おう{と/が}、私は自分の子供を信じている。","japanese_furigana":"人が何と言おう{と/が}、私は自分の子供を信じている。","english":"Whatever (other) people say, I believe my child."},{"japanese":"頑固と言われよう{と/が}馬鹿と言われよう{と/が}、私は自分の信じることをやります。","japanese_furigana":"頑固と言われよう{と/が}馬鹿と言われよう{と/が}、私は自分の信じることをやります。","english":"Even if people say I''m stubborn or stupid, I''ll do what I believe."}]'::jsonb),
    ('1b2c51d0-910e-4129-9ced-baf33f8f303e'::uuid,ARRAY['(i) {V/Adjective い} informal ように']::text[],ARRAY['Use this construction to express An adverbial form of ようだ. An adverbial form of ようだ']::text[],ARRAY['The core sense is An adverbial form of ようだ; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私が言うように書いて下さい。","japanese_furigana":"私が言うように書いて下さい。","english":"Please write it down as I tell you."},{"japanese":"今日は春になったように暖かい・暖かいです。","japanese_furigana":"今日は春になったように暖かい・暖かいです。","english":"Today is as warm as if it had become spring."}]'::jsonb),
    ('9245db71-7d63-4344-84ef-9a8c0ec85b8f'::uuid,ARRAY['Vinformal nonpast {potential/ negative} ように']::text[],ARRAY['Use this construction to express Do something in such a way that ~.. Do something in such a way that ~.']::text[],ARRAY['The core sense is Do something in such a way that ~.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"読めるように字を奇麗に書いて下さい。","japanese_furigana":"読めるように字を奇麗に書いて下さい。","english":"Please write it neatly so that I can read it."},{"japanese":"風邪を引かないように気をつけている・います。","japanese_furigana":"風邪を引かないように気をつけている・います。","english":"I''m taking care of myself so that I don''t catch a cold."}]'::jsonb),
    ('d93c62b0-7889-4532-b382-b79523d6af7a'::uuid,ARRAY['Vvolitional にも (～ ない )']::text[],ARRAY['Use this construction to express A conjunctive phrase that indicates concession: “even though someone tries to do something, he/she cannot do it for some reason”.. A conjunctive phrase that indicates concession: “even though someone tries to do something, he/she cannot do it for some reason”.']::text[],ARRAY['【Related Expression: ようたって; にも; たくても(~ない); たくとも(~ない)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"徹に連絡しようにも電話番号もメールアドレスも知らない。","japanese_furigana":"徹に連絡しようにも電話番号もメールアドレスも知らない。","english":"Even though I want to contact Toru, I don''t know either her phone number or her e-mail address."},{"japanese":"ひどく頭が痛くて起きようにも起きられない。","japanese_furigana":"ひどく頭が痛くて起きようにも起きられない。","english":"I have a terrible headache, and I cannot get up even though I want to."}]'::jsonb),
    ('c422f456-7ea8-4d4a-ab08-5679f978a81e'::uuid,ARRAY['Vvolitional ものなら']::text[],ARRAY['Use this construction to express A conjunctive phrase that presents an undesirable hypothetical situation.. A conjunctive phrase that presents an undesirable hypothetical situation.']::text[],ARRAY['【Related Expression: たりしたら】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"山野氏は非常に時間に厳しい人で、面会時間に5分も遅れようものなら以後二度と会ってはもらえない。","japanese_furigana":"山野氏は非常に時間に厳しい人で、面会時間に5分も遅れようものなら以後二度と会ってはもらえない。","english":"Mr. Yamano is very strict about time; if you happen to be even five minutes late for an appointment with him, he won''t meet with you again."},{"japanese":"私はタバコの煙に特に敏感で、近くで吸われようものならもう何事にも集中できなくなってしまう。","japanese_furigana":"私はタバコの煙に特に敏感で、近くで吸われようものならもう何事にも集中できなくなってしまう。","english":"I''m particularly sensitive to cigarette smoke, so when someone is smoking nearby, I cannot concentrate on anything."}]'::jsonb),
    ('d3444b89-3892-4174-bbe3-4bc34a0ca52c'::uuid,ARRAY['(i) Vinformal nonpast ( より ) はか ( に )( は ) ない']::text[],ARRAY['Use this construction to express A phrase that conveys the idea that there is no other choice than to do something, or that something is true of only one of a select few things.. A phrase that conveys the idea that there is no other choice than to do something, or that something is true of only one of a select few things.']::text[],ARRAY['【Related Expression: なければならない; なければいけない; ざるを得ない; に~ない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"公共の交通機関がないので、自分の車で行く(より)ほか(に)(は)ない。","japanese_furigana":"公共の交通機関がないので、自分の車で行く(より)ほか(に)(は)ない。","english":"Since there is no public transportation, we have no other choice but to go there in your/my car."},{"japanese":"新聞はニューヨークタイムズのほか(に)は読まない。","japanese_furigana":"新聞はニューヨークタイムズのほか(に)は読まない。","english":"I read nothing but the New York Times. (literally: I don''t read any newspaper other than the New York Times.)"}]'::jsonb),
    ('ef0d662f-8334-4234-a3c9-09e06a529e1d'::uuid,ARRAY['Canonical pattern: 〜より（起点）']::text[],ARRAY['Use this construction to express A particle which indicates a set point in terms of space or time.. A particle which indicates a set point in terms of space or time.']::text[],ARRAY['【Related Expression: から1】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"メキシコは赤道より北にある・あります。","japanese_furigana":"メキシコは赤道より北にある・あります。","english":"Mexico is located north of the equator."},{"japanese":"この線より内側に入ってはいけません。","japanese_furigana":"この線より内側に入ってはいけません。","english":"You must not get inside this line."}]'::jsonb),
    ('3a984eba-c755-4633-9843-53d204522014'::uuid,ARRAY['(i) Group 1 verbs Vneg れる']::text[],ARRAY['Use this construction to express A state or an action cannot be controlled by someone or something.. A state or an action cannot be controlled by someone or something.']::text[],ARRAY['【Related Expression: お~になる; られる2】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"一郎は花子に騙された・騙されました。","japanese_furigana":"一郎は花子に騙された・騙されました。","english":"Ichiro was deceived by Hanako."},{"japanese":"ジェーンはフレッドに夜遅くアパートに来られた・来られました。","japanese_furigana":"ジェーンはフレッドに夜遅くアパートに来られた・来られました。","english":"Fred came to Jane''s apartment late at night (and Jane was unhappy)."}]'::jsonb),
    ('29243244-5223-4641-859a-27b6590b76f9'::uuid,ARRAY['ろくに Vnegative ない']::text[],ARRAY['Use this construction to express A structure that is used to indicate that something animate does not or cannot do something satisfactorily/sufficiently/properly.. A structure that is used to indicate that something animate does not or cannot do something satisfactorily/sufficiently/properly.']::text[],ARRAY['The core sense is A structure that is used to indicate that something animate does not or cannot do something satisfactorily/sufficiently/properly.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"飛行機の中ではろくに寝られなかった。","japanese_furigana":"飛行機の中ではろくに寝られなかった。","english":"On the plane I couldn''t sleep well."},{"japanese":"ろくに勉強もしないで試験を受けたので、全然出来なかった。","japanese_furigana":"ろくに勉強もしないで試験を受けたので、全然出来なかった。","english":"I took the exam without studying properly, so it was a disaster (literally: I couldn''t do well at all)."}]'::jsonb),
    ('e1ececbb-f86b-43ff-8da6-068a6783438c'::uuid,ARRAY['Canonical pattern: 〜わ']::text[],ARRAY['Use this construction to express A sentence final particle used in weak assertive or volitional sentences by a female speaker.. A sentence final particle used in weak assertive or volitional sentences by a female speaker.']::text[],ARRAY['The core sense is A sentence final particle used in weak assertive or volitional sentences by a female speaker.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私も明日のパーティーに行くわ。","japanese_furigana":"私も明日のパーティーに行くわ。","english":"I''ll go to tomorrow''s party, too."},{"japanese":"大木さんはもう帰りましたわ。","japanese_furigana":"大木さんはもう帰りましたわ。","english":"Mr. Ooki has already gone home."}]'::jsonb),
    ('c67c77ea-daed-4c93-8701-554bc414a4d1'::uuid,ARRAY['(i) S1informal nonpast わ S2informal nonpast わ']::text[],ARRAY['Use this construction to express A structure that emphatically presents actions, events or states as examples or reasons, or indicates that someone does something or something happens to a great extent.. A structure that emphatically presents actions, events or states as examples or reasons, or indicates that someone does something or something happens to a great extent.']::text[],ARRAY['【Related Expression: やら~やら】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"飛行機は12時間も遅れるわ荷物はなくなるわ(で)、今度の旅行は最悪だった。","japanese_furigana":"飛行機は12時間も遅れるわ荷物はなくなるわ(で)、今度の旅行は最悪だった。","english":"The ﬂight was delayed l2 hours, and my luggage was lost; this trip was the worst."},{"japanese":"客が来るわ来るわ、またたく間に小さい店はいっぱいになった。","japanese_furigana":"客が来るわ来るわ、またたく間に小さい店はいっぱいになった。","english":"Customers came in one after another, and in the blink of an eye, the small shop had ﬁlled up."}]'::jsonb),
    ('89b42307-8f47-412e-98f5-02236855188d'::uuid,ARRAY['(i) {V/Adjective い}informal nonpast わけがない']::text[],ARRAY['Use this construction to express A phrase which negates the existence of a reason to believe that someone does something or is in some state, or that something takes place; or which negates a possibility of someone''s doing something or being in some state, or something''s taking place.. A phrase which negates the existence of a reason to believe that someone does something or is in some state, or that something takes place; or which negates a possibility of someone''s doing something or being in some state, or something''s taking place.']::text[],ARRAY['【Related Expression: はずがない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"こんな易しい仕事が君に出来ないわけがない。","japanese_furigana":"こんな易しい仕事が君に出来ないわけがない。","english":"There is no reason why you cannot do such an easy job."},{"japanese":"日本語がそんなに速くマスター出来るわけがない。","japanese_furigana":"日本語がそんなに速くマスター出来るわけがない。","english":"It is impossible to be able to master Japanese that quickly."}]'::jsonb),
    ('8f23cdf1-9b0c-4323-99df-27590cd36559'::uuid,ARRAY['(i) {V/Adjective い} わけだ']::text[],ARRAY['Use this construction to express A phrase which presents a fact or truth known to the hearer as an introduction to a following statement, or which gives emphasis to a fact or truth which the hearer might not know.. A phrase which presents a fact or truth known to the hearer as an introduction to a following statement, or which gives emphasis to a fact or truth which the hearer might not know.']::text[],ARRAY['【Related Expression: のだ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"福田先生の死で私達はリーダーを失ってしまったわけですが、今後は私達自身でこの会を発展させていかなければなりません。","japanese_furigana":"福田先生の死で私達はリーダーを失ってしまったわけですが、今後は私達自身でこの会を発展させていかなければなりません。","english":"As you know, we lost our leader with Professor Fukuda''s death. From now on we have to advance this group by ourselves."},{"japanese":"戦争は大きな犠牲を伴うわけで、我々は何としてもこれを避けなければならない。","japanese_furigana":"戦争は大きな犠牲を伴うわけで、我々は何としてもこれを避けなければならない。","english":"War is accompanied by great sacrifice, as you know, and we have to avoid it at any cost."}]'::jsonb),
    ('adbe4ad1-c8d6-4c23-8969-1ed48d8ad663'::uuid,ARRAY['(i) {V/Adjective い} informal わけだ']::text[],ARRAY['Use this construction to express The speaker''s conclusion obtained through deductive, logical judgment or calculation on the basis of what he has heard or read.. The speaker''s conclusion obtained through deductive, logical judgment or calculation on the basis of what he has heard or read.']::text[],ARRAY['【Related Expression: はずだ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"毎日三時間も日本語を勉強いるんですか。よく出来るわけですね。","japanese_furigana":"毎日三時間も日本語を勉強いるんですか。よく出来るわけですね。","english":"Are you studying Japanese (as long as) three hours every day? No wonder your Japanese is good."},{"japanese":"明日試験ですか。じゃあ今晩忙しいわけですね。","japanese_furigana":"明日試験ですか。じゃあ今晩忙しいわけですね。","english":"Do you have an exam tomorrow? Then, you must be busy tonight."}]'::jsonb),
    ('113534ed-53b0-4d73-a965-8ad704f38bbc'::uuid,ARRAY['(i) {V/Adjective い}informal ( という ) わけではない']::text[],ARRAY['Use this construction to express A phrase which is used to deny what is implied in the previous or following statement.. Import a full grammar_guide JSON object to complete this canonical guide.']::text[],ARRAY['The core sense is A phrase which is used to deny what is implied in the previous or following statement.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"この問題を解決するのは非常に難しい。しかし、不可能（だ）というわけではない。","japanese_furigana":"この問題を解決するのは非常に難しい。しかし、不可能（だ）というわけではない。","english":"It is very difficult to solve this problem. But that does not mean that it is impossible (to solve)."},{"japanese":"君の考えに反対するわけではないが、そのやり方でうまくいくだろうか。","japanese_furigana":"君の考えに反対するわけではないが、そのやり方でうまくいくだろうか。","english":"I don''t mean to oppose your idea, but I wonder if things will go well using that approach."}]'::jsonb),
    ('b0e6840a-7b02-439b-81ed-cbf62802ded5'::uuid,ARRAY['(i) Vinformal nonpast わけにはいかない']::text[],ARRAY['Use this construction to express A phrase which is used to indicate that one cannot do something due to an external circumstance.. A phrase which is used to indicate that one cannot do something due to an external circumstance.']::text[],ARRAY['【Related Expression: ことが出来る; なければならない; られない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"来週は期末試験があるから、今週末は遊んでいるわけにはいかない。","japanese_furigana":"来週は期末試験があるから、今週末は遊んでいるわけにはいかない。","english":"There will be final examinations next week, so I cannot fool around this weekend."},{"japanese":"親友の結婚式だから、出席しないわけにはいかない。","japanese_furigana":"親友の結婚式だから、出席しないわけにはいかない。","english":"Since it is the wedding of my close friend I have no other choice but to attend it."}]'::jsonb),
    ('e0d1182b-3cc9-44a8-8487-1fdcc14ea6ae'::uuid,ARRAY['Canonical pattern: 〜を（感情の対象・原因）']::text[],ARRAY['Use this construction to express A particle that marks the cause of some human emotion.. A particle that marks the cause of some human emotion.']::text[],ARRAY['The core sense is A particle that marks the cause of some human emotion.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"次郎は父の死を悲しんだ・悲しみました。","japanese_furigana":"次郎は父の死を悲しんだ・悲しみました。","english":"Jiro was saddened at his father''s death."},{"japanese":"次郎は父が死んだこと・のを悲しんだ・悲しみした。","japanese_furigana":"次郎は父が死んだこと・のを悲しんだ・悲しみした。","english":"Jiro was sad that his father died."}]'::jsonb),
    ('e0625119-717f-4f37-8e20-04ac7ce8a607'::uuid,ARRAY['Canonical pattern: 〜を（目的語）']::text[],ARRAY['Use this construction to express A particle which marks a direct object.. A particle which marks a direct object.']::text[],ARRAY['The core sense is A particle which marks a direct object.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私は日本語を勉強している・います。","japanese_furigana":"私は日本語を勉強している・います。","english":"I''m studying Japanese."},{"japanese":"前田さんは昨日車を買った。","japanese_furigana":"前田さんは昨日車を買った。","english":"Mr. Maeda bought a car yesterday."}]'::jsonb),
    ('8d5f1b4d-71e0-4ad7-9c27-745e91ca9f2b'::uuid,ARRAY['Canonical pattern: 〜を（経路）']::text[],ARRAY['Use this construction to express A particle which indicates a space in/on/across/through/along which someone or something moves.. A particle which indicates a space in/on/across/through/along which someone or something moves.']::text[],ARRAY['【Related Expression: で1】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は五番街を歩いた・歩きました。","japanese_furigana":"私は五番街を歩いた・歩きました。","english":"I walked along Fifth Avenue."},{"japanese":"公園を通って帰りましょう。","japanese_furigana":"公園を通って帰りましょう。","english":"Let''s go home passing through the park."}]'::jsonb),
    ('10e8675c-f154-424d-b152-c3953ea8888e'::uuid,ARRAY['Canonical pattern: 〜を（起点）']::text[],ARRAY['Use this construction to express A particle that marks the location from which some movement begins.. A particle that marks the location from which some movement begins.']::text[],ARRAY['【Related Expression: から1】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は朝七時半に家を出る・出ます。","japanese_furigana":"私は朝七時半に家を出る・出ます。","english":"I leave home at 7.30 in the morning."},{"japanese":"汽車がトンネルを出た。","japanese_furigana":"汽車がトンネルを出た。","english":"A train came out of the tunnel."}]'::jsonb),
    ('cd9b3245-b6f0-44a8-b293-2bb10c252560'::uuid,ARRAY['Noun をおいてほかに ( は )～ ない']::text[],ARRAY['Use this construction to express A phrase that means “there is nothing else besides X”.. A phrase that means “there is nothing else besides X”.']::text[],ARRAY['【Related Expression: 以外に~ない; のほかに~ない; 一番; もっとも】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本語を短期間で習得したいのならこの学校をおいてほかに(は)ない。","japanese_furigana":"日本語を短期間で習得したいのならこの学校をおいてほかに(は)ない。","english":"If you want to learn Japanese in a short period of time, there is no other school (that you should consider) but this one."},{"japanese":"これほど多くの作品を手がけた監督はY氏をおいてほかにいない。","japanese_furigana":"これほど多くの作品を手がけた監督はY氏をおいてほかにいない。","english":"No other director has been involved with as many works as Mr. Y."}]'::jsonb),
    ('935fc466-906f-43b5-a025-9364a19baac3'::uuid,ARRAY['Noun をはじめ ( として )']::text[],ARRAY['Use this construction to express A phrase that is used to give a primary example.. A phrase that is used to give a primary example.']::text[],ARRAY['【Related Expression: だけで(は)なく~(も)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私のうちでは、父をはじめ（として）、家族全員スポーツが好きだ。","japanese_furigana":"私のうちでは、父をはじめ（として）、家族全員スポーツが好きだ。","english":"In my family, starting with my father, all of us like sports."},{"japanese":"キャシーは、寿司をはじめとして、日本食なら何でも食べる。","japanese_furigana":"キャシーは、寿司をはじめとして、日本食なら何でも食べる。","english":"Starting with sushi, Cathy eats any Japanese cuisine."}]'::jsonb),
    ('94398542-da41-4235-946a-d0f9d560cde9'::uuid,ARRAY['(i) Noun をめぐって']::text[],ARRAY['Use this construction to express A compound particle meaning “concerning; over”, which is used with an issue over which different opinions, ideas, etc., are expressed or exchanged.. A compound particle meaning “concerning; over”, which is used with an issue over which different opinions, ideas, etc., are expressed or exchanged.']::text[],ARRAY['【Related Expression: に関して; について】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"モノレール建設をめぐって市民の意見が対立している。","japanese_furigana":"モノレール建設をめぐって市民の意見が対立している。","english":"Citizens'' opinions are divided over the monorail construction."},{"japanese":"無駄な公共事業をめぐる批判の声が強まっている。","japanese_furigana":"無駄な公共事業をめぐる批判の声が強まっている。","english":"(Voices of) Criticism concerning wasteful public projects is growing stronger."}]'::jsonb),
    ('e5db0652-d107-4513-9f57-24e91dbe49fc'::uuid,ARRAY['(i) Noun をものともせず']::text[],ARRAY['Use this construction to express A phrase indicating that someone does something bravely/fearlessly in spite of unfavourable circumstances.. A phrase indicating that someone does something bravely/fearlessly in spite of unfavourable circumstances.']::text[],ARRAY['【Related Expression: にもかかわらず】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼女は重度の身体障害をものともせず、自分の人生をつかみとった。","japanese_furigana":"彼女は重度の身体障害をものともせず、自分の人生をつかみとった。","english":"Despite severe physical handicaps, she took charge of her own life."},{"japanese":"彼は日本語がしゃべれないのをものともせず、身振り手振りで日本を旅行して歩いた。","japanese_furigana":"彼は日本語がしゃべれないのをものともせず、身振り手振りで日本を旅行して歩いた。","english":"Undaunted by his inability to speak Japanese, he travelled around Japan communicating with gestures and signs."}]'::jsonb),
    ('5a13f0b7-65de-49b1-9a86-d6b9d06764eb'::uuid,ARRAY['(i) NP をよそに']::text[],ARRAY['Use this construction to express A compound particle that expresses someone’s indifference to warnings, criticism, advice, accusations, opposition, anxiety, wishes, eagerness, provocative actions, etc.. A compound particle that expresses someone’s indifference to warnings, criticism, advice, accusations, opposition, anxiety, wishes, eagerness, provocative actions, etc.']::text[],ARRAY['The core sense is A compound particle that expresses someone’s indifference to warnings, criticism, advice, accusations, opposition, anxiety, wishes, eagerness, provocative actions, etc.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"首相は国民の批判をよそにイラク戦争支持を表明した。","japanese_furigana":"首相は国民の批判をよそにイラク戦争支持を表明した。","english":"Setting aside people''s criticism, the prime minister declared his support for the Iraq War."},{"japanese":"青春時代、友達がデートに明け暮れるのをよそに、僕は家に一人こもってSFを読んでいた。","japanese_furigana":"青春時代、友達がデートに明け暮れるのをよそに、僕は家に一人こもってSFを読んでいた。","english":"During my adolescent years, I secluded myself at home and read science ﬁction, ignoring my friends, who were spending all their time dating."}]'::jsonb),
    ('945150c0-647e-4a63-8657-bd349cd36695'::uuid,ARRAY['Noun を中心に']::text[],ARRAY['Use this construction to express A phrase that means “with something/someone at the centre”.. A phrase that means “with something/someone at the centre”.']::text[],ARRAY['【Related Expression: を中心と/にして】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"東京を中心に大雨が降った。","japanese_furigana":"東京を中心に大雨が降った。","english":"There was heavy rain, mostly in and around Tokyo."},{"japanese":"東南アジアを中心に鳥インフルエンザが急速に広がっている。","japanese_furigana":"東南アジアを中心に鳥インフルエンザが急速に広がっている。","english":"Bird ﬂu is spreading rapidly, primarily in Southeast Asia."}]'::jsonb),
    ('c04f1dd6-ce65-4bb9-940b-39f305d9eeb8'::uuid,ARRAY['(i) Noun を介して']::text[],ARRAY['Use this construction to express A compound particle that introduces a medium through which someone does something or something happens to someone or something.. A compound particle that introduces a medium through which someone does something or something happens to someone or something.']::text[],ARRAY['【Related Expression: をとうして; によって/より】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"今、現地の代理人を介して製造元と価格の交渉をしている。","japanese_furigana":"今、現地の代理人を介して製造元と価格の交渉をしている。","english":"We are negotiating the price with the manufacturer through a local agent now."},{"japanese":"インターネットを介して音楽や映画を配信できるようになった。","japanese_furigana":"インターネットを介して音楽や映画を配信できるようになった。","english":"Music and movies can be distributed via the Internet now."}]'::jsonb),
    ('7cad911a-2795-4956-b439-6df7571d6de3'::uuid,ARRAY['(i) Noun 1 ({、/ と/や}Noun 2 ) を問わず']::text[],ARRAY['Use this construction to express A compound particle that means “without questioning”.. A compound particle that means “without questioning”.']::text[],ARRAY['【Related Expression: にかかわらず; に関係なく; によらず】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この会社は、経験があれば学歴を問わず採用してくれる。","japanese_furigana":"この会社は、経験があれば学歴を問わず採用してくれる。","english":"This company will employ you regardless of your educational background if you have (relevant work) experience."},{"japanese":"卒業後就職するか進学するかを問わず、担任との個人面談を受けなければならない。","japanese_furigana":"卒業後就職するか進学するかを問わず、担任との個人面談を受けなければならない。","english":"You have to have an individual consultation with your homeroom teacher whether you work or go on to college after graduation."}]'::jsonb),
    ('862c93e5-ffcf-4f5e-a80d-f8af9ab88673'::uuid,ARRAY['(i) Noun を禁じ得ない']::text[],ARRAY['Use this construction to express A phrase that is used when one cannot control emotions or reactions caused by emotions.. A phrase that is used when one cannot control emotions or reactions caused by emotions.']::text[],ARRAY['The core sense is A phrase that is used when one cannot control emotions or reactions caused by emotions.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"このような無責任な行いに対して怒りを禁じ得ない。","japanese_furigana":"このような無責任な行いに対して怒りを禁じ得ない。","english":"I cannot hold back my anger at such an irresponsible deed."},{"japanese":"その感動的な光景を見て、涙がこみ上げてくるのを禁じ得なかった。","japanese_furigana":"その感動的な光景を見て、涙がこみ上げてくるのを禁じ得なかった。","english":"Seeing the moving scene, I could not keep my tears from welling up."}]'::jsonb),
    ('2896e9a7-88fd-4a0f-bd0e-d2f6a89c5235'::uuid,ARRAY['Noun を通して']::text[],ARRAY['Use this construction to express A compound particle that is used to indicate a medium through which something is done or time through which something takes place.. A compound particle that is used to indicate a medium through which something is done or time through which something takes place.']::text[],ARRAY['【Related Expression: を通じて】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は親しい友達を通してそのピアニストと知り合いになった。","japanese_furigana":"私は親しい友達を通してそのピアニストと知り合いになった。","english":"I became acquainted with the pianist through a close friend of mine."},{"japanese":"私は一年を通して五回ぐらい海外に行っている。","japanese_furigana":"私は一年を通して五回ぐらい海外に行っている。","english":"I go abroad about 5 times a year (literally: throughout the year)."}]'::jsonb),
    ('70c1b246-2e45-40d9-936d-ea4d980e3965'::uuid,ARRAY['Vnegative んとする Exception:する→せんとする']::text[],ARRAY['Use this construction to express A phrase meaning for “someone to try to do something” or for “something to be about to occur”.. A phrase meaning for “someone to try to do something” or for “something to be about to occur”.']::text[],ARRAY['【Related Expression: ようとする】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"教授の言わんとすることが学生に伝わらないのは、たいてい教授の方が悪いのだ。","japanese_furigana":"教授の言わんとすることが学生に伝わらないのは、たいてい教授の方が悪いのだ。","english":"It is usually a professor who is to blame when his students don''t comprehend what he tries to convey."},{"japanese":"太陽はまさに山の稜線に沈まんとしていた。","japanese_furigana":"太陽はまさに山の稜線に沈まんとしていた。","english":"The sun was about to sink behind the mountain ridge."}]'::jsonb),
    ('360c544a-c465-4654-ae55-8995db9b1142'::uuid,ARRAY['一 [Counter] として ～ ない']::text[],ARRAY['Use this construction to express A structure that means “not a single one".. A structure that means “not a single one".']::text[],ARRAY['【Related Expression: {Interrogative word] ひと/いち [counter]~ない; ひと/いち [counter] たりとも~ない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"うちの課には一人として英語を話せる者がいない。","japanese_furigana":"うちの課には一人として英語を話せる者がいない。","english":"Not a single person in my section can speak English."},{"japanese":"この資料室には一冊として役に立つ本がない。","japanese_furigana":"この資料室には一冊として役に立つ本がない。","english":"There''s not a single useful book in this library."}]'::jsonb),
    ('69c7de25-4066-4f40-b52c-9375654e492d'::uuid,ARRAY['一切 Vnegative ない']::text[],ARRAY['Use this construction to express A structure that means “not at all”.. A structure that means “not at all”.']::text[],ARRAY['【Related Expression: 全然~ない; 全く~ない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"飛行機事故の原因は一切分からない。","japanese_furigana":"飛行機事故の原因は一切分からない。","english":"We have no idea what caused the airplane accident."},{"japanese":"この製品には遺伝子組み換え大豆は一切使用していません。","japanese_furigana":"この製品には遺伝子組み換え大豆は一切使用していません。","english":"For this product we haven''t used any genetically modiﬁed soybeans at all."}]'::jsonb),
    ('95919eea-0aca-44c7-a36a-2dfea3a7f76c'::uuid,ARRAY['(i) Vinformal nonpast 一方だ']::text[],ARRAY['Use this construction to express A phrase indicating that “something happens continuously” or “someone does something repeatedly”.. A phrase indicating that “something happens continuously” or “someone does something repeatedly”.']::text[],ARRAY['【Related Expression: ばかりだ; ますます; だけ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"物価は上げる一方だ。","japanese_furigana":"物価は上げる一方だ。","english":"(Commodity) prices are rising steadily."},{"japanese":"久子は私にものを頼む一方で、何もしてくれたことがない。","japanese_furigana":"久子は私にものを頼む一方で、何もしてくれたことがない。","english":"Hisako is always requesting favours but has never done anything for me."}]'::jsonb),
    ('e44b3967-31ac-4c0c-9f26-67a136ce56f7'::uuid,ARRAY['Nounは 一方では S1 Conjunction, 他方では S2']::text[],ARRAY['Use this construction to express A structure used to describe two concurring, contrastive actions/states of someone or something.. A structure used to describe two concurring, contrastive actions/states of someone or something.']::text[],ARRAY['The core sense is A structure used to describe two concurring, contrastive actions/states of someone or something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"神田先生は、一方では大学で物理学を教えながら、他方では日本語の研究をなさっている。","japanese_furigana":"神田先生は、一方では大学で物理学を教えながら、他方では日本語の研究をなさっている。","english":"Professor Kanda teaches physics at college on the one hand and does research on Japanese language on the other."},{"japanese":"あの男は、一方では静かな日本画を描いたりしているが、他方ではサッカーのような激しいスポーツをしている。","japanese_furigana":"あの男は、一方では静かな日本画を描いたりしているが、他方ではサッカーのような激しいスポーツをしている。","english":"That man draws quiet Japanese paintings on the one hand, but plays a very competitive sport like soccer on the other."}]'::jsonb),
    ('eedfd0f9-02a3-4f4a-b568-71b92a07fbf9'::uuid,ARRAY['Noun 上']::text[],ARRAY['Use this construction to express A suffix which indicates the idea of "from the viewpoint of," "for the sake of," "for the reason," or "in terms of".. A suffix which indicates the idea of "from the viewpoint of," "for the sake of," "for the reason," or "in terms of".']::text[],ARRAY['【Related Expression: の上では】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この映画は教育上よくない。","japanese_furigana":"この映画は教育上よくない。","english":"This film is not good from an educational point of view."},{"japanese":"便宜上私がこの部屋の鍵を預かっているんです。","japanese_furigana":"便宜上私がこの部屋の鍵を預かっているんです。","english":"I keep the key to this room for the sake of convenience."}]'::jsonb),
    ('afe10f92-2998-46a5-8828-406dfa31d2e8'::uuid,ARRAY['(i) Vて 下さい']::text[],ARRAY['Use this construction to express An auxiliary verb which indicates a polite request.. An auxiliary verb which indicates a polite request.']::text[],ARRAY['The core sense is An auxiliary verb which indicates a polite request.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"日本語で書いて下さい。","japanese_furigana":"日本語で書いて下さい。","english":"Please write in Japanese."},{"japanese":"英語を使わないで下さい。","japanese_furigana":"英語を使わないで下さい。","english":"Please don''t use English."}]'::jsonb),
    ('72c09fdb-dab7-4571-8970-c47432decaf5'::uuid,ARRAY['(i) Vinformal nonpast 中を']::text[],ARRAY['Use this construction to express A phrase that specifies space or time in/through which someone/something does something.. A phrase that specifies space or time in/through which someone/something does something.']::text[],ARRAY['【Related Expression: ところを; 時に】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"冷たい風が｛吹く/吹いている｝中を１０キロも歩いた。","japanese_furigana":"冷たい風が｛吹く/吹いている｝中を１０キロも歩いた。","english":"When a cold wind was blowing I walked as much as 10 kilometres."},{"japanese":"お忙しい中をいらしていただき、申し訳ございません。","japanese_furigana":"お忙しい中をいらしていただき、申し訳ございません。","english":"Thank you very much (literally: I''m sorry) for coming when you are (so) busy."}]'::jsonb),
    ('2a0224ab-2f73-48da-95c7-f11f106f7555'::uuid,ARRAY['(i) 何 Noun 1 ない Noun 2']::text[],ARRAY['Use this construction to express A structure indicating that something doesn''t exist at all.. A structure indicating that something doesn''t exist at all.']::text[],ARRAY['【Related Expression: 全く~ない; 全然~ない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼女は何不自由ない裕福な家庭で育った。","japanese_furigana":"彼女は何不自由ない裕福な家庭で育った。","english":"She grew up in a comfortable and rich family without inconveniences."},{"japanese":"マイケルは何問題なく日本での留学生活を続けている。","japanese_furigana":"マイケルは何問題なく日本での留学生活を続けている。","english":"Michael is continuing his study abroad in Japan without any problems."}]'::jsonb),
    ('f19373c6-3600-450d-bc23-bfee0984d25a'::uuid,ARRAY['(i) 何 (Number)+Counter も']::text[],ARRAY['Use this construction to express A phrase that indicates there is a large number of things, people, etc.. A phrase that indicates there is a large number of things, people, etc.']::text[],ARRAY['The core sense is A phrase that indicates there is a large number of things, people, etc.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私は日本へは何回も行ったことがあるが、韓国と中国はまだだ。","japanese_furigana":"私は日本へは何回も行ったことがあるが、韓国と中国はまだだ。","english":"I have been to Japan many times, but I''ve never been to Korea or China."},{"japanese":"私は日本語の辞書を何十冊も持っている。","japanese_furigana":"私は日本語の辞書を何十冊も持っている。","english":"I have dozens of Japanese dictionaries."}]'::jsonb),
    ('f1fc2410-1085-439f-b512-6eeca48bf421'::uuid,ARRAY['Canonical pattern: 〜何でも']::text[],ARRAY['Use this construction to express A phrase that indicates the speaker''s uncertainty about something.. A phrase that indicates the speaker''s uncertainty about something.']::text[],ARRAY['The core sense is A phrase that indicates the speaker''s uncertainty about something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"何でも山本さんは奥さんと別れて、一人で暮らしているそうですよ。","japanese_furigana":"何でも山本さんは奥さんと別れて、一人で暮らしているそうですよ。","english":"I don''t know for sure, but they say that Mr. Yamamoto has separated from his wife and lives alone."},{"japanese":"何でもこの辺は物価が非常に高いそうですよ。","japanese_furigana":"何でもこの辺は物価が非常に高いそうですよ。","english":"I don''t know for sure, but they say things are expensive in this neighbourhood."}]'::jsonb),
    ('0bfca46a-1b0f-401a-9422-ceb294e478b0'::uuid,ARRAY['何も ～ ない']::text[],ARRAY['Use this construction to express A structure indicating that an action is taken for no good reason.. A structure indicating that an action is taken for no good reason.']::text[],ARRAY['The core sense is A structure indicating that an action is taken for no good reason.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"何もそんなに怒ることはないよ。","japanese_furigana":"何もそんなに怒ることはないよ。","english":"You have no good reason to get so angry."},{"japanese":"良性の腫瘍だから、何もそんなに心配する必要はない。","japanese_furigana":"良性の腫瘍だから、何もそんなに心配する必要はない。","english":"It''s a benign tumour, so you don''t need to worry about it too much."}]'::jsonb),
    ('7ab30948-ac62-4677-a20a-054b306737c4'::uuid,ARRAY['(i) 何ら Noun {が/も} ない']::text[],ARRAY['Use this construction to express A structure that is used to express a strong negative statement.. A structure that is used to express a strong negative statement.']::text[],ARRAY['【Related Expression: 何も~ない; 少しも~ない; ちっとも~ない; 全然~ない; 全く~ない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本の大学教育の現状は何ら改善されていない。","japanese_furigana":"日本の大学教育の現状は何ら改善されていない。","english":"The state of Japanese college education has not improved at all."},{"japanese":"会社側は労働組合に対して何らの誠意ある回答もしなかった。","japanese_furigana":"会社側は労働組合に対して何らの誠意ある回答もしなかった。","english":"The company (literally: company side) has failed to give any sincere reply to the labour union (whatsoever)."}]'::jsonb),
    ('19854de5-2b3c-4389-abb8-cf09f85f4977'::uuid,ARRAY['何らかの Noun']::text[],ARRAY['Use this construction to express A phrase used to indicate that the exact nature of something represented by the noun cannot be speciﬁed.. A phrase used to indicate that the exact nature of something represented by the noun cannot be speciﬁed.']::text[],ARRAY['【Related Expression: なん(い)かの】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"何らかの原因で走行中で電車が急停車した。","japanese_furigana":"何らかの原因で走行中で電車が急停車した。","english":"Due to some (unknown) cause the train stopped suddenly."},{"japanese":"私たちが患う病気は、たいてい、何らかの意味でゲノム関係があります。","japanese_furigana":"私たちが患う病気は、たいてい、何らかの意味でゲノム関係があります。","english":"Most of the illnesses that we get are linked in some way with genomes."}]'::jsonb),
    ('140f5cb6-92c8-41e0-9303-ada3e653c9fe'::uuid,ARRAY['例の Noun']::text[],ARRAY['Use this construction to express A phrase which signals that the referent of the following noun phrase is definite and that the speaker expects the hearer to understand what the referent is.. A phrase which signals that the referent of the following noun phrase is definite and that the speaker expects the hearer to understand what the referent is.']::text[],ARRAY['【Related Expression: は】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"例のプロジェクトはどうなりましたか。","japanese_furigana":"例のプロジェクトはどうなりましたか。","english":"What happened to the project (in question)?"},{"japanese":"今年の忘年会はまた例の中華料理屋だそうだ。","japanese_furigana":"今年の忘年会はまた例の中華料理屋だそうだ。","english":"I heard that this year''s year-end party is going to be at that Chinese restaurant again."}]'::jsonb),
    ('04bc464e-4bf5-469d-a433-e53b5776ecb6'::uuid,ARRAY['(i) Number+Counter 分 ( の Noun)']::text[],ARRAY['Use this construction to express A suffix which indicates the amount of something.. A suffix which indicates the amount of something.']::text[],ARRAY['【Related Expression: 前】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ガソリンを十ドル分入れておきました。","japanese_furigana":"ガソリンを十ドル分入れておきました。","english":"I put in ten dollars worth of gas."},{"japanese":"私は今日三日分の仕事を片付けた。","japanese_furigana":"私は今日三日分の仕事を片付けた。","english":"Today I did three days worth of work."}]'::jsonb),
    ('54336cdf-130e-499b-984a-fa9b628d6467'::uuid,ARRAY['(i) Noun {の/である/だった/であった} 割に ( は )']::text[],ARRAY['Use this construction to express A phrase that expresses the idea that something is not in proportion to what one would normally expect.. A phrase that expresses the idea that something is not in proportion to what one would normally expect.']::text[],ARRAY['【Related Expression: にしては】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この店のサービスランチは値段の割に(は)おいしくボリュームがある。","japanese_furigana":"この店のサービスランチは値段の割に(は)おいしくボリュームがある。","english":"The bargain lunch at this restaurant is tasty and the portions are generous for the price."},{"japanese":"ビルはよく勉強している割に(は)成績が伸びない。","japanese_furigana":"ビルはよく勉強している割に(は)成績が伸びない。","english":"For all his hard work, Bill''s grades don''t seem to improve. / Although Bill studies hard, his grades do not improve."}]'::jsonb),
    ('c52bd16f-7451-4942-acbd-c83808f018c2'::uuid,ARRAY['(i) (Number+) Counter 単位で']::text[],ARRAY['Use this construction to express A phrase that indicates the smallest amount, number or unit of something (or people) involved.. A phrase that indicates the smallest amount, number or unit of something (or people) involved.']::text[],ARRAY['【Related Expression: ずつ; ごとに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"このATMは千円単位でお金を引き出すことができる。","japanese_furigana":"このATMは千円単位でお金を引き出すことができる。","english":"You can withdraw money from this ATM in multiples of 1,000 yen."},{"japanese":"この社内調査では課単位でリサイクル実施率を調べる。","japanese_furigana":"この社内調査では課単位でリサイクル実施率を調べる。","english":"This in-house investigation will examine the recycling rate for each section."}]'::jsonb),
    ('08d5e36f-7e81-4007-ac48-0ea47161da12'::uuid,ARRAY['(i) Noun 1 及び Noun 2']::text[],ARRAY['Use this construction to express A particle that connects two nouns or noun phrases.. A particle that connects two nouns or noun phrases.']::text[],ARRAY['【Related Expression: と; そして; 並びに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"使用した機種及びソフトウエアを表１に示す。","japanese_furigana":"使用した機種及びソフトウエアを表１に示す。","english":"The computer models and software we used are listed in Table 1."},{"japanese":"本奨学金への応募資格は、日本国籍を有すること、及び国内の四年制大学に在籍する学生であることである。","japanese_furigana":"本奨学金への応募資格は、日本国籍を有すること、及び国内の四年制大学に在籍する学生であることである。","english":"The qualifications for applying for this scholarship require (literally: are) that you be a Japanese citizen and a student at a four-year college in this country."}]'::jsonb),
    ('15e93379-4828-436a-a001-ea8e35795dd5'::uuid,ARRAY['(i) Noun 向け だ']::text[],ARRAY['Use this construction to express A suffix that adds the meaning of “aimed at”. A suffix that adds the meaning of “aimed at”']::text[],ARRAY['【Related Expression: よう; 向き】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"このギター曲集は初心者向けだ。","japanese_furigana":"このギター曲集は初心者向けだ。","english":"This collection of guitar pieces is for beginners."},{"japanese":"この秋はアジア向け（の）産業用ロボットの販売が好調だ。","japanese_furigana":"この秋はアジア向け（の）産業用ロボットの販売が好調だ。","english":"This autumn, sales of industrial robots for Asia have been good."}]'::jsonb),
    ('753a7272-37a0-4fc6-9945-4ee642133365'::uuid,ARRAY['(i) Last name 君']::text[],ARRAY['Use this construction to express A suffix attached to the first or last name of a male equal or to the first or last name of a person whose status or rank is lower than the speaker’s.. A suffix attached to the first or last name of a male equal or to the first or last name of a person whose status or rank is lower than the speaker’s.']::text[],ARRAY['【Related Expression: 様 (ちゃん; さん)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"もし、もし、一郎君いますか。","japanese_furigana":"もし、もし、一郎君いますか。","english":"Hello, is Ichiro in?"},{"japanese":"田口君が来年結婚するそうだ。","japanese_furigana":"田口君が来年結婚するそうだ。","english":"I heard that Mr. Taguchi will get married next year."}]'::jsonb),
    ('8aba2c88-6bf1-483f-b367-d54c36a9dd8e'::uuid,ARRAY['Canonical pattern: 〜屋']::text[],ARRAY['Use this construction to express A suffix attached to names of stores, inns and Japanese style restaurants or to persons engaged in certain occupations. A suffix attached to names of stores, inns and Japanese style restaurants or to persons engaged in certain occupations']::text[],ARRAY['The core sense is A suffix attached to names of stores, inns and Japanese style restaurants or to persons engaged in certain occupations; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"花屋 本屋 薬屋 肉屋 パチンコ屋 パン屋 魚屋 酒屋","japanese_furigana":"花屋 本屋 薬屋 肉屋 パチンコ屋 パン屋 魚屋 酒屋","english":"Florist bookstore drug store butcher pinball parlor bakery fishmonger liquor store"},{"japanese":"酒屋さんに電話してビールを三ダース持って来てもらった。","japanese_furigana":"酒屋さんに電話してビールを三ダース持って来てもらった。","english":"I called the man at the liquor store and had him bring me three dozen beers."}]'::jsonb),
    ('6c084ae3-5a27-4eae-a310-eaceae627671'::uuid,ARRAY['Vます うる / える']::text[],ARRAY['Use this construction to express An auxiliary verb that expresses possibility.. An auxiliary verb that expresses possibility.']::text[],ARRAY['【Related Expression: ことが出来る; られる】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"二十一世紀に日本語は国際語になり得ると思う。","japanese_furigana":"二十一世紀に日本語は国際語になり得ると思う。","english":"I think it''s possible for the Japanese language to become an international language in the 21st century."},{"japanese":"株の変動はいつでも起こり得る。","japanese_furigana":"株の変動はいつでも起こり得る。","english":"The fluctuation of stocks can happen any time."}]'::jsonb),
    ('6a8b9fcc-3bdb-46ba-aa6f-860685d5892b'::uuid,ARRAY['(i) 思うに 、 Sentence。']::text[],ARRAY['Use this construction to express A phrase indicating that the subsequent statement is the speaker’s/writer’s personal view.. A phrase indicating that the subsequent statement is the speaker’s/writer’s personal view.']::text[],ARRAY['【Related Expression: 考えるに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"(私が)思うに、文化は宗教の一種だ。","japanese_furigana":"(私が)思うに、文化は宗教の一種だ。","english":"In my view, culture is a kind of religion."},{"japanese":"医学界の体質を思うに、当然医者と製薬会社の癒着はあると思う。","japanese_furigana":"医学界の体質を思うに、当然医者と製薬会社の癒着はあると思う。","english":"Considering the nature of the medical world, I believe there is collusion between doctors and pharmaceutical companies."}]'::jsonb),
    ('d1ea0b90-59f9-45c7-8d81-afdeaabbd7ec'::uuid,ARRAY['(i) Nounの 恐れがある']::text[],ARRAY['Use this construction to express A phrase that means “it is feared (that)". A phrase that means “it is feared (that)"']::text[],ARRAY['【Related Expression: きけんせいがる; 心配がある; かのうせいがある; かもしれない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"台風の影響で、西日本は大雨の恐れがある。","japanese_furigana":"台風の影響で、西日本は大雨の恐れがある。","english":"Due to the typhoon (literally: the typhoon''s inﬂuence), there is a chance of heavy rain across Western Japan."},{"japanese":"この戦争は第二のベトナム戦争になる恐れがある。","japanese_furigana":"この戦争は第二のベトナム戦争になる恐れがある。","english":"This war could become a second Vietnam War. (literally: There is a risk that this war will become a second Vietnam War.)"}]'::jsonb),
    ('17a31026-fb78-4985-8aaf-13b9d93b9ca3'::uuid,ARRAY['(i) {Adjective い informal/Adjective な stem な/Vinformal} + (Noun の) +Vます 方をする']::text[],ARRAY['Use this construction to express A phrase to indicate a manner of doing something.. A phrase to indicate a manner of doing something.']::text[],ARRAY['【Related Expression: ように】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"林田先生は厳しい教え方をする。","japanese_furigana":"林田先生は厳しい教え方をする。","english":"Professor Hayashida teaches in a strict manner."},{"japanese":"昭は変わったものの見方をする。","japanese_furigana":"昭は変わったものの見方をする。","english":"Akira views things in a peculiar fashion."}]'::jsonb),
    ('42c59530-abda-4730-a05d-9529cf94875b'::uuid,ARRAY['Canonical pattern: 〜様']::text[],ARRAY['Use this construction to express A suffix (originally meaning ''appearance'') that indicates the speaker''s/writer''s politeness towards someone.. A suffix (originally meaning ''appearance'') that indicates the speaker''s/writer''s politeness towards someone.']::text[],ARRAY['【Related Expression: ちゃん; 君; さん】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"王様の耳は驢馬の耳だ。","japanese_furigana":"王様の耳は驢馬の耳だ。","english":"The King''s ears are donkey ears."},{"japanese":"神様を信じますか。","japanese_furigana":"神様を信じますか。","english":"Do you believe in God?"}]'::jsonb),
    ('76ba4885-5a99-4aea-8052-7ea0f8a95558'::uuid,ARRAY['滅多に ～ Vnegative ない']::text[],ARRAY['Use this construction to express A structure that indicates extremely low frequency.. A structure that indicates extremely low frequency.']::text[],ARRAY['【Related Expression: たまには; あまり~ない; ほとんど~ない; たましか~ない; 時たましか~ない; 全然~ない; 全く~ない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この辺りでは地震は滅多に起きない。","japanese_furigana":"この辺りでは地震は滅多に起きない。","english":"Earthquakes seldom occur in this area."},{"japanese":"日本の父親は忙しいので、週末でも滅多にうちにいない。","japanese_furigana":"日本の父親は忙しいので、週末でも滅多にうちにいない。","english":"Japanese fathers are so busy that even on weekends they are seldom at home."}]'::jsonb),
    ('b6c881fe-0ca5-4afc-a829-f5a5c5d05621'::uuid,ARRAY['Number+Counter 目']::text[],ARRAY['Use this construction to express A suffix which represents an ordinal number.. A suffix which represents an ordinal number.']::text[],ARRAY['The core sense is A suffix which represents an ordinal number.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私の車は右から二台目です。","japanese_furigana":"私の車は右から二台目です。","english":"My car is the second one from the right."},{"japanese":"それは上から三つ目の引き出しに入っています。","japanese_furigana":"それは上から三つ目の引き出しに入っています。","english":"It is in the third drawer from the top."}]'::jsonb),
    ('30939837-8c33-46b7-b5aa-93033b51a227'::uuid,ARRAY['Canonical pattern: 〜確かに〜が']::text[],ARRAY['Use this construction to express A structure which expresses the idea "indeed ~ but".. A structure which expresses the idea "indeed ~ but".']::text[],ARRAY['【Related Expression: ことは~が】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この車は確かに魅力的だが、値段が高すぎる。","japanese_furigana":"この車は確かに魅力的だが、値段が高すぎる。","english":"This car is certainly attractive, but the price is too high."},{"japanese":"そのパーティーのことは確かに聞いたが、いつだったか思い出せない。","japanese_furigana":"そのパーティーのことは確かに聞いたが、いつだったか思い出せない。","english":"I certainly heard about the party, but I don''t remember when it is going to be."}]'::jsonb),
    ('46ed856c-c65b-45a3-9609-d564cd2fac35'::uuid,ARRAY['(i) 見るからに Adjective(い/な) stemそうだ']::text[],ARRAY['Use this construction to express A phrase indicating that something can be (obviously) recognized through visual cues.. A phrase indicating that something can be (obviously) recognized through visual cues.']::text[],ARRAY['【Related Expression: 明らかに; いかにも】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"太陽の光をたっぷり浴びたみかんは、見るからにおいしそうだ。","japanese_furigana":"太陽の光をたっぷり浴びたみかんは、見るからにおいしそうだ。","english":"The sun-bathed mandarin oranges look really delicious."},{"japanese":"彼女が身につけているものは見るからに高級品だった。","japanese_furigana":"彼女が身につけているものは見るからに高級品だった。","english":"What she wears is obviously of high quality."}]'::jsonb),
    ('c3d6e78e-d688-4501-9f6c-7fd84d353fda'::uuid,ARRAY['(i) {V/Adjectiveい} informal+Nominalは 言うまでもない 。']::text[],ARRAY['Use this construction to express A phrase indicating that what the speaker/writer expresses is generally known but that he/she presents it as a reminder.. A phrase indicating that what the speaker/writer expresses is generally known but that he/she presents it as a reminder.']::text[],ARRAY['The core sense is A phrase indicating that what the speaker/writer expresses is generally known but that he/she presents it as a reminder.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"寿司が日本の代表的な料理であることは言うまでもない。","japanese_furigana":"寿司が日本の代表的な料理であることは言うまでもない。","english":"It goes without saying that sushi is representative of Japanese cuisine."},{"japanese":"言うまでもなく、日本の社会は世界一の高齢化社会になっている。","japanese_furigana":"言うまでもなく、日本の社会は世界一の高齢化社会になっている。","english":"That Japan has become the most rapidly aging society in the world goes without saying."}]'::jsonb),
    ('01589d45-9db0-43c3-a9c3-e8d804376d0b'::uuid,ARRAY['(i) 言ってみれば Sentence。 Where Sentence is a simile or a metaphor']::text[],ARRAY['Use this construction to express A phrase signalling a comparison (including the use of simile and metaphor), a deﬁnition, or an explanation.. A phrase signalling a comparison (including the use of simile and metaphor), a deﬁnition, or an explanation.']::text[],ARRAY['【Related Expression: 言わば; 例えて言えば; (例えて)言うならば】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"言ってみれば、人生は航海（のようなもの）だ。","japanese_furigana":"言ってみれば、人生は航海（のようなもの）だ。","english":"Figuratively speaking, life is (like) a voyage."},{"japanese":"彼女の家は、言ってみれば、お城のように作られている。","japanese_furigana":"彼女の家は、言ってみれば、お城のように作られている。","english":"You could say her house is built like a castle."}]'::jsonb),
    ('f4b1b452-302f-4a4e-921c-d015abbcf204'::uuid,ARRAY['Noun 1 と言わず Noun 2 と言わず']::text[],ARRAY['Use this construction to express A structure indicating that something is the case not only for A and B but also for many other places, things, etc., of X, to which A and B belong. A structure indicating that something is the case not only for A and B but also for many other places, things, etc., of X, to which A and B belong']::text[],ARRAY['【Related Expression: だろうが/と~だろうが/と; であろうが/と~であろうが/と; であれ~であれ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"友達の引っ越しを手伝ったら、翌日肩と言わず腰と言わず体のあちこちが痛んだ。","japanese_furigana":"友達の引っ越しを手伝ったら、翌日肩と言わず腰と言わず体のあちこちが痛んだ。","english":"I helped my friend move. Then, the next day my shoulders, my back and every other part of my body ached."},{"japanese":"武史の部屋は、壁と言わず天井と言わず、いたるところにサッカーの写真が貼ってあった。","japanese_furigana":"武史の部屋は、壁と言わず天井と言わず、いたるところにサッカーの写真が貼ってあった。","english":"In Takeshi''s room, pictures of soccer were posted on the walls, the ceiling and everywhere else."}]'::jsonb),
    ('6239bc7f-2bf0-4fea-8829-14e23e448000'::uuid,ARRAY['(i) Noun (time) 限り']::text[],ARRAY['Use this construction to express A suffix which expresses the idea of "(last) only until" or "limited".. A suffix which expresses the idea of "(last) only until" or "limited".']::text[],ARRAY['The core sense is A suffix which expresses the idea of "(last) only until" or "limited".; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"今度限りで彼のパーティーには行かないつもりだ。","japanese_furigana":"今度限りで彼のパーティーには行かないつもりだ。","english":"This is the last time I am going to any of his parties."},{"japanese":"切符は一人二枚限りです。","japanese_furigana":"切符は一人二枚限りです。","english":"Tickets are limited to two per person."}]'::jsonb),
    ('bea4e98f-1564-4f4d-9a09-0cc8227e0bd1'::uuid,ARRAY['(i) Vinformal 限り']::text[],ARRAY['Use this construction to express A conjunction which expresses the idea "as long as (a certain condition is met)" or "as long as (= to the extent)".. A conjunction which expresses the idea "as long as (a certain condition is met)" or "as long as (= to the extent)".']::text[],ARRAY['【Related Expression: あいだは; うちは】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私がここにいる限り心配は無用です。","japanese_furigana":"私がここにいる限り心配は無用です。","english":"As long as I am here, you don''t have to worry."},{"japanese":"田中さんが来ない限りこの会議は始められない。","japanese_furigana":"田中さんが来ない限りこの会議は始められない。","english":"As long as Mr. Tanaka is not here (literally: does not come), we cannot begin this meeting."}]'::jsonb)
)
update public.japanese_grammar_guides g
set formation=case when coalesce(array_length(g.formation,1),0)=0 then e.formation_value else g.formation end,
    usage=case when coalesce(array_length(g.usage,1),0)=0 then e.usage_value else g.usage end,
    nuance=case when coalesce(array_length(g.nuance,1),0)=0 then e.nuance_value else g.nuance end,
    reference_examples=case when jsonb_typeof(coalesce(g.reference_examples,'[]'::jsonb))='array' and jsonb_array_length(coalesce(g.reference_examples,'[]'::jsonb))=0 then e.examples_value else g.reference_examples end,
    updated_at=now()
from enrichment e
where g.id=e.grammar_id and g.user_id=(select user_id from private.app_owner);

commit;
